pub const OUT_LABELS: [&str; 6] = ["AN1/2", "PH3/4", "AS1/2", "ADAT3/4", "ADAT5/6", "ADAT7/8"];

/// Strips redundant prefixes baked into a channel's stored name before it's
/// shown in a strip header — "PCM " for playback channels, "OUT " for
/// output bus pairs (`profile.rs`'s `format!("OUT {}", pair.left)`). Both
/// are already conveyed by the strip's own type tag badge right next to
/// the name, so keeping them in the text just wastes width for no extra
/// information — on an output like "OUT ADAT3" that was enough to push the
/// collapse button (`header_row`) almost entirely off the card.
pub fn short_label(name: &str) -> &str {
    name.strip_prefix("PCM ")
        .or_else(|| name.strip_prefix("OUT "))
        .unwrap_or(name)
}

/// Combines a linked output pair's two per-channel names ("AN1"/"AN2",
/// "PH3"/"PH4", "ADAT7"/"ADAT8") into the historical combined bus label
/// ("AN1/2", "PH3/4", "ADAT7/8") — matches what `tuxmix-usb`'s output
/// list used before it became per-channel (see `usb.rs`'s `open()`),
/// and what TotalMix itself shows for a linked stereo bus. Falls back to
/// `"{left}/{right}"` unmodified if `right` doesn't end in digits (not
/// expected for this device's own channel names, but harmless).
pub(crate) fn pair_bus_label(left: &str, right: &str) -> String {
    let right_num: String = right.chars().skip_while(|c| !c.is_ascii_digit()).collect();
    if right_num.is_empty() {
        format!("{left}/{right}")
    } else {
        format!("{left}/{right_num}")
    }
}

pub fn type_tag(t: ChannelType) -> (&'static str, iced::Color) {
    // The muted type family: quiet enough to live in a graphite UI
    // without fighting the white "engaged" states for attention, but
    // still separable hues for scanning a long strip row. Mic, line and
    // instrument keep their console associations (blue, neutral, amber);
    // the two digital ports share a violet.
    // Each hue is pulled toward the theme's ink until it reads on the
    // floors (`theme::readable`): the pastels were tuned for dark grounds
    // and faded into Daylight's.
    let (label, hue) = match t {
        ChannelType::Mic => ("MIC", theme::TAG_MIC),
        ChannelType::Instrument => ("INST", theme::TAG_INST),
        ChannelType::Line => ("LINE", theme::TAG_LINE),
        ChannelType::SPDIF => ("SPDIF", theme::TAG_DIGITAL),
        ChannelType::ADAT => ("ADAT", theme::TAG_DIGITAL),
    };
    (label, theme::readable_on_floors(hue))
}

/// Tag colors for the bus rows (not real `ChannelType`s, so not part of
/// `type_tag`) — kept distinct from the input-type palette above so PB/OUT
/// don't just blend into the secondary-text gray everything else uses.
/// Readable on the theme's floors like the input tags.
pub fn pb_tag() -> iced::Color {
    theme::readable_on_floors(theme::TAG_PB)
}
pub fn out_tag() -> iced::Color {
    theme::readable_on_floors(theme::TAG_OUT)
}

pub fn parse_db_input(s: &str) -> Option<f32> {
    let raw = s.trim().to_lowercase();
    if raw.is_empty() || raw == "-inf" || raw == "-\u{221e}" {
        return Some(0.0);
    }
    raw.replace(',', ".")
        .parse::<f32>()
        .ok()
        .map(|db| (10f32.powf(db / 20.0)).clamp(0.0, 2.0))
}

/// How much quieter PAD makes a mic input: 11 dB, the Babyface Pro FS
/// manual's figure, twice ("a PAD can attenuate the input signal by 11 dB";
/// the Settings panel's "PAD. Applies -11 dB damping"; docs/ui-spec.md
/// agrees). Audra said and dipped 20 until critique #58 caught it.
pub const PAD_DB: u32 = 11;

/// A level's dB to one decimal, without a unit. A level a hair under
/// unity (a fader set from a dB value comes back as 0.99999) reads 0.0,
/// not "-0.0". Above 0 dB it is signed, "+2.9", as gain reads "+38"
/// (critique #57: a thin dash was all that told 2.9 from -2.9).
pub fn db_number(vol: f32) -> String {
    let db = 20.0 * vol.log10();
    if db.abs() < 0.05 {
        "0.0".into()
    } else if db > 0.0 {
        format!("+{db:.1}")
    } else {
        format!("{db:.1}")
    }
}

// ── Device enum ──────────────────────────────────────────────────

pub enum DeviceHandle {
    #[cfg(feature = "alsa")]
    Real(BabyfacePro),
    Mock(MockBabyfacePro),
    /// The proprietary USB backend (the TotalMix protocol). On Linux
    /// with the device in proprietary mode this is the path that
    /// actually works.
    Usb(BabyfaceProUsb),
}

impl DeviceHandle {
    /// The last samples of inputs `inputs` (a pair averaged) and their rate,
    /// for the EQ panel's live spectrum (`live_spectrum`); an empty list
    /// stops the tap keeping them. The simulation answers with a voice at
    /// its meter's level.
    pub fn input_scope(&self, inputs: &[usize]) -> Option<(Vec<f32>, u32)> {
        match self {
            DeviceHandle::Mock(d) => {
                if inputs.is_empty() {
                    return None;
                }
                let level = inputs.iter().map(|&i| d.input_meter(i)).fold(0.0f32, f32::max);
                let t = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map_or(0.0, |d| (d.as_secs_f64() % 1000.0) as f32);
                Some((crate::live_spectrum::mock_voice(level, crate::spectrum::FFT_N, t), 48_000))
            }
            DeviceHandle::Usb(_) => None,
            #[cfg(feature = "alsa")]
            DeviceHandle::Real(d) => d.input_scope(inputs),
        }
    }

    /// Point the *mock* at the class-compliant personality's feature set.
    /// Only tests ever need this: every real backend answers for itself,
    /// and `TUXMIX_MOCK_CC` covers looking at the gated UI by hand.
    #[cfg(test)]
    pub(crate) fn set_protocol_features(&mut self, on: bool) {
        if let DeviceHandle::Mock(dev) = self {
            dev.set_protocol_features(on);
        }
    }

    /// Point the *mock* at "unplugged", or back. Tests only; every real
    /// backend answers for itself, and `TUXMIX_MOCK_DISCONNECT` covers
    /// looking at the disconnected chip by hand.
    #[cfg(test)]
    fn set_connected(&mut self, on: bool) {
        if let DeviceHandle::Mock(dev) = self {
            dev.set_connected(on);
        }
    }

    /// A press of the simulated front panel's DIM button. Tests only.
    #[cfg(test)]
    fn press_dim_button(&mut self) {
        if let DeviceHandle::Mock(dev) = self {
            dev.press_dim_button();
        }
    }

    /// What the simulated hardware carries at a crosspoint. Tests only.
    #[cfg(test)]
    pub(crate) fn mock_hardware(&self, channel: ChannelId, output: usize) -> Option<(f32, i8)> {
        match self {
            DeviceHandle::Mock(dev) => Some(dev.hardware_crosspoint(channel, output)),
            _ => None,
        }
    }
}

/// EQ numbers from here up are output channels' (`DeviceHandle::eq_of`):
/// the EQ panel, its presets and Undo speak one number for both.
pub const OUT_EQ: usize = 100;

/// An output's EQ before it was ever set: on the unit nothing, so off,
/// the bands TotalMix starts with but flat, and no low cut.
pub fn flat_output_eq() -> tuxmix_core::channel::InputEq {
    use tuxmix_core::channel::{EqBand, EqBandType, InputEq};
    InputEq {
        enabled: false,
        bands: [
            EqBand { band_type: EqBandType::LowShelf, freq_hz: 100, q: 0.9, gain_db: 0.0 },
            EqBand { band_type: EqBandType::Bell, freq_hz: 1000, q: 0.9, gain_db: 0.0 },
            EqBand { band_type: EqBandType::HighShelf, freq_hz: 8000, q: 0.9, gain_db: 0.0 },
        ],
        low_cut_freq_hz: 0,
        low_cut_slope_db_oct: 12,
    }
}

macro_rules! delegate {
    ($self:expr, $method:ident($($arg:expr),*)) => { match $self {
        DeviceHandle::Mock(d) => d.$method($($arg),*),
        DeviceHandle::Usb(d) => d.$method($($arg),*),
        #[cfg(feature = "alsa")]
        DeviceHandle::Real(d) => d.$method($($arg),*),
    } };
    ($self:expr, $method:ident) => { match $self {
        DeviceHandle::Mock(d) => d.$method(),
        DeviceHandle::Usb(d) => d.$method(),
        #[cfg(feature = "alsa")]
        DeviceHandle::Real(d) => d.$method(),
    } };
}

