/// The auto-saved scene put back on a device that has just opened. The
/// driver keeps the unit's own levels and this writes none; the USB
/// backend can't read them back and writes the whole scene, so there the
/// outputs go out silent and are handed back (channel, level) to glide up
/// (`start_output_rises`; issue #22: a start or a replug wrote every level
/// at once).
fn restore_auto_scene_gently(device: &mut DeviceHandle, scene: &Scene) -> (Result<(), tuxmix_core::Error>, Vec<(usize, f32)>) {
    if !matches!(device, DeviceHandle::Usb(_)) {
        return (device.restore_auto_scene(scene), Vec::new());
    }
    let rising: Vec<(usize, f32)> = scene.outputs.iter().enumerate().map(|(ch, o)| (ch, o.volume)).collect();
    let mut quiet = scene.clone();
    for out in &mut quiet.outputs {
        out.volume = 0.0;
    }
    (device.restore_auto_scene(&quiet), rising)
}

/// Outputs handed back by `restore_auto_scene_gently` glide up to their
/// levels, as Recall's rise does.
fn start_output_rises(state: &mut TuxMix, rising: &[(usize, f32)]) {
    let now = Instant::now();
    for &(ch, to) in rising {
        if to > 0.0 {
            state.level_ramps.insert(ch, (-60.0, 20.0 * to.max(1e-6).log10(), now));
        }
    }
}

/// The mix as it is now, as a snapshot holds it (for `main`'s demo setup).
pub fn capture_demo_scene(state: &TuxMix) -> Scene {
    crate::control_room::capture_scene(state)
}

/// Reads the themes folder again, keeping every theme choice (the one
/// picked, the day and night ones, the one showing) by its id, and returns
/// what could not be read.
fn reload_user_themes(state: &mut TuxMix) -> Vec<String> {
    let id_of = |i: usize| theme::themes().get(i).map_or("audra", |t| t.id);
    let (picked, day, night, shown) = (
        id_of(state.theme),
        id_of(state.theme_schedule.day),
        id_of(state.theme_schedule.night),
        id_of(state.theme_shown),
    );
    let (custom, problems) = match crate::usertheme::dir() {
        Some(dir) => crate::usertheme::load_dir(&dir),
        None => (Vec::new(), Vec::new()),
    };
    theme::register(custom);
    state.theme = theme::theme_index(picked);
    state.theme_schedule.day = theme::theme_index(day);
    state.theme_schedule.night = theme::theme_index(night);
    state.theme_shown = theme::theme_index(shown);
    crate::themetime::follow(state, crate::themetime::FADE_PICKED);
    state.prefs_dirty = true;
    problems
}

/// The sequencer client of the chosen Mackie Control surface, while it is
/// connected.
pub(crate) fn mackie_client(state: &TuxMix) -> Option<i32> {
    let name = state.mackie.device.as_deref()?;
    state.midi_ports.iter().find(|p| p.name == name).map(|p| p.client)
}



/// Opens `url` in the browser. Fire and forget: the browser is not our
/// child process, and a minimal session may have no `xdg-open` to hand it
/// to at all.
/// Set by `--screenshot` (captures and their probes): nothing then opens
/// on the desktop (the owner, 2026-11-10: a reviewer's test runs kept
/// opening the recordings folder in the file manager).
pub static CAPTURE_RUN: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

fn open_url(url: &str) {
    // Never from a capture run or a test (2026-11-10, the owner: "what's
    // the deal with this home music Audra that keeps opening up empty
    // cosmic windows all the time?": the keyboard test for Audra settings
    // pressed Recordings' Open folder on every test run).
    if cfg!(test) || CAPTURE_RUN.load(std::sync::atomic::Ordering::Relaxed) {
        log::info!("capture run or test: not opening {url}");
        return;
    }
    if let Err(e) = std::process::Command::new("xdg-open")
        .arg(url)
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .spawn()
    {
        log::warn!("Could not open {url}: {e}");
    }
}

/// A mic preset that raises a preamp by more than this many dB glides it
/// up (`RAMP_FOR`) rather than jumping (2026-11-04, the critique: a
/// preset's 48V waited for a click while its gain landed at once; the
/// owner chose a ramp). Drops stay instant.
pub(crate) const RAMP_OVER_DB: u32 = 6;

/// How far Shift+← or Shift+→ moves the keyboard's strip's pan.
const PAN_KEY_STEP: i8 = 5;

/// The longest name a channel, a snapshot, a preset or a workspace takes,
/// in characters (issue #22: there was no cap; a pasted paragraph
/// overflowed every strip and list). TotalMix's own names are shorter.
pub(crate) const NAME_MAX: usize = 32;

/// `name` cut to `NAME_MAX` characters, as it is typed.
pub(crate) fn capped_name(name: String) -> String {
    if name.chars().count() <= NAME_MAX {
        name
    } else {
        name.chars().take(NAME_MAX).collect()
    }
}
/// How long a preset's gain takes to come up.
pub(crate) const RAMP_FOR: Duration = Duration::from_millis(300);

/// The most one step may take a `RAMP_FOR` glide on, as a share of the
/// way: 60 dB × 0.099 stays under the app's 6 dB (`RAMP_OVER_DB`), as the
/// Dim glide's cap does (`control_room::EASE_STEP_MAX`; OpenCode's job 33:
/// 0.11 made 6.6 dB steps). A late tick (Audra busy starting up, the
/// window being moved) then takes a longer glide, never a bigger step (the
/// scout, 2026-11-12: the first tick after start-up could land a recovered
/// send or a preset's gain in one step).
pub(crate) const RAMP_STEP_MAX: f32 = 0.099;

/// Which glide's step time `capped_share` keeps (`ramps_stepped_at`).
#[derive(Clone, Copy)]
pub(crate) enum RampKind {
    Gain = 0,
    Level = 1,
    Fader = 2,
    FxReturn = 3,
}

/// The step clock for a kind of glide: the time of its last step, and now
/// kept as the next one's (forgotten while none of that kind runs).
pub(crate) fn ramp_step_clock(state: &mut TuxMix, kind: RampKind, now: Instant, running: bool) -> Option<Instant> {
    let slot = &mut state.ramps_stepped_at[kind as usize];
    let prev = *slot;
    *slot = running.then_some(now);
    prev
}

/// A glide's share of the way at `now` (0 to 1), from `since` over `over`,
/// but no more than `RAMP_STEP_MAX` past where it stood at the last step
/// (`prev`), and the start to keep: moved on when the step was held back,
/// so the next one measures from where the glide really is.
/// The most one glide step may write over the level the fader has now:
/// just under `RAMP_OVER_DB`, as `capped_share`'s 5.94 dB.
const RAMP_STEP_DB: f32 = 5.94;

pub(crate) fn capped_share(since: Instant, prev: Option<Instant>, now: Instant, over: Duration, span_db: f32) -> (f32, Instant) {
    let share = |at: Instant| (at.saturating_duration_since(since).as_secs_f32() / over.as_secs_f32()).clamp(0.0, 1.0);
    let by_time = share(now);
    let was = prev.map_or(0.0, share);
    // Also in dB: a glide longer than 60 dB (from -60 to +6) took 6.5 dB a
    // step at 0.099 (OpenCode's job 38). Never more than 5.94 dB.
    let most = RAMP_STEP_MAX.min(5.94 / span_db.abs().max(1e-3));
    let t = by_time.min(was + most);
    if t < by_time {
        (t, now.checked_sub(over.mul_f32(t)).unwrap_or(since))
    } else {
        (t, since)
    }
}

/// Moves every gain on its way up (`TuxMix::gain_ramps`) to where it is
/// due at `now`, in whole dB, and drops those that have arrived. Written
/// on the tick after the poll's comparison, so a ramp's steps never read
/// as the unit's own (`note_outside_gains`).
pub(crate) fn step_gain_ramps(state: &mut TuxMix, now: Instant) {
    let ramps: Vec<(usize, (u32, u32, Instant))> = state.gain_ramps.iter().map(|(&i, &r)| (i, r)).collect();
    let prev = ramp_step_clock(state, RampKind::Gain, now, !ramps.is_empty());
    for (idx, (from, to, since)) in ramps {
        let (t, since) = capped_share(since, prev, now, RAMP_FOR, to as f32 - from as f32);
        state.gain_ramps.insert(idx, (from, to, since));
        let due = (from as f32 + (to as f32 - from as f32) * t).round() as u32;
        if state.device.inputs().get(idx).and_then(|c| c.gain) != Some(due) {
            if let Err(e) = state.device.set_input_gain(idx, due) {
                fail(state, "set_input_gain", &e);
                state.gain_ramps.remove(&idx);
                continue;
            }
            // OSC remotes follow the gain up, as a knob turn tells them.
            notify_osc(state, OscOutbound::Gain(idx, due));
        }
        if t >= 1.0 {
            state.gain_ramps.remove(&idx);
        }
    }
}

/// Applies `scene` as the mix (undo, redo, a snapshot, a workspace), then
/// takes every preamp gain it raised by more than `RAMP_OVER_DB` back down
/// and lets it glide up, as a mic preset's does (the reviewer, 2026-11-04:
/// a Redo put +25 dB back on a preamp in one step).
#[cfg(test)]
pub(crate) fn apply_mix_scene(state: &mut TuxMix, scene: &Scene) -> Result<(), tuxmix_core::Error> {
    let levels_before = output_levels(state);
    apply_mix_scene_from(state, scene, &levels_before)
}

/// The output levels on the unit now: what `apply_mix_scene_from` measures
/// a scene's rises from. Taken before the Control Room lets go of its
/// overrides (`control_room::release`), so a Dim undone by an Undo, a
/// snapshot or a workspace glides up with the rest (issue #22: measured
/// after, the undim was the "before" and came at full step, +20 dB).
pub(crate) fn output_levels(state: &TuxMix) -> Vec<f32> {
    state.device.outputs().iter().map(|o| o.volume).collect()
}

/// A send of `cid` to mix `out` brought to `to` by a scene or a recovery:
/// raised by more than `RAMP_OVER_DB` it glides up from where it is, that
/// channel alone, as a fader's rise does (issue #22, the owner's yes: a
/// snapshot that took a mic's send from −∞ to 0 dB put it in the speakers
/// at once); else it lands.
pub(crate) fn set_send_gently(state: &mut TuxMix, cid: ChannelId, out: usize, to: f32, now: Instant) {
    set_send_gently_via(state, cid, out, to, now, GlideVia::OneChannel);
}

/// `set_send_gently`, its glide's steps written `via`.
pub(crate) fn set_send_gently_via(state: &mut TuxMix, cid: ChannelId, out: usize, to: f32, now: Instant, via: GlideVia) {
    let was = state.device.volume(cid, out).unwrap_or(0.0);
    let db = |v: f32| 20.0 * v.max(1e-6).log10();
    if db(to) > db(was) + RAMP_OVER_DB as f32 {
        state.fader_glides.insert(
            (cid, out),
            FaderGlide { from_db: db(was).max(-60.0), to_db: db(to), to, since: now, via },
        );
    } else {
        let _ = write_send(state, out, |d| d.set_volume(cid, out, to));
    }
}

/// The mix another Audra (the terminal one, or a second window) saved to
/// the shared file, taken in while this one runs: the snapshot's gentle
/// way (OpenCode's job 49: the overrides let go in one write, up to 60 dB,
/// and the mix written raw, a raised gain or level in one step). Not an
/// Undo step: it isn't a change of yours. (At quit the overrides are let
/// go already, and no glide would run after it: `SaveNow` keeps the raw
/// write.)
pub(crate) fn sync_other_scene(state: &mut TuxMix, their: &Scene) {
    // A change from outside: Undo would now take back the other Audra's
    // mix with the notice's, so the notice's key goes (the advisor: kept
    // while it applies, the key's window is no longer 5 s).
    state.notice_undo = None;
    state.undo_tip_kept = None;
    let levels = output_levels(state);
    let voices = plain_voices_in_streams(state);
    crate::control_room::release_holding(state, Instant::now());
    if let Err(e) = apply_mix_scene_from(state, their, &levels) {
        fail(state, "apply_scene", &e);
    }
    crate::control_room::reapply(state);
    say_stream_lost_voice(state, &voices, "The mix saved by another Audra", "Undo (Ctrl+Z) takes it back.");
}

/// `apply_mix_scene`, its output rises measured from `levels_before`.
/// `apply_mix_scene_inner`, and Make it heard's memory forgotten when the
/// scene that came in moved the send or the return it raised (Fable's
/// review of issue #45: any Undo forgot it, a gain's too, and a refused
/// scene).
pub(crate) fn apply_mix_scene_from(state: &mut TuxMix, scene: &Scene, levels_before: &[f32]) -> Result<(), tuxmix_core::Error> {
    // In dB, within 0.05 dB: a glide's end comes back a rounding step off
    // (Fable's round 2).
    let levels = |state: &TuxMix| state.made_heard.map(|m| (crate::fx::send_db(state), crate::fx::returns_to_keep(state).get(m.pair).map_or(-200.0, |r| crate::fx::vol_db(r.1).max(-200.0))));
    let moved = |a: (f32, f32), b: (f32, f32)| (a.0 - b.0).abs() > 0.05 || (a.1 - b.1).abs() > 0.05;
    let before = levels(state);
    let result = apply_mix_scene_inner(state, scene, levels_before);
    if result.is_ok() && before.zip(levels(state)).is_some_and(|(b, a)| moved(b, a)) {
        state.made_heard = None;
    }
    result
}

fn apply_mix_scene_inner(state: &mut TuxMix, scene: &Scene, levels_before: &[f32]) -> Result<(), tuxmix_core::Error> {
    // Another mix comes back: Quick setup's lit card and its "… is set"
    // card no longer describe it (critique #80 A 7).
    state.setup_done = None;
    state.my_setup_lit = false;
    // Another shape than the unit's is refused before anything is written
    // (OpenCode's job 40: its lists replaced the unit's channels).
    scene.check_shape(state.device.inputs().len(), state.device.playbacks().len(), state.device.outputs().len())?;
    scene.check_lists(state.device.inputs(), state.device.playbacks())?;
    let before: Vec<Option<u32>> = state.device.inputs().iter().map(|c| c.gain).collect();
    let levels_before = levels_before.to_vec();
    // Every input's and playback's send to every mix, before.
    let pairs = state.device.output_pair_count();
    let sources: Vec<ChannelId> = (0..state.device.inputs().len())
        .map(ChannelId::Input)
        .chain((0..state.device.playbacks().len()).map(ChannelId::Playback))
        .collect();
    let sends_before: Vec<(ChannelId, usize, f32)> = sources
        .iter()
        .flat_map(|&cid| (0..pairs).map(move |out| (cid, out)))
        // What the card plays: less than the model while an override let
        // go just before still holds the cell (`release_holding`).
        .filter_map(|(cid, out)| {
            let v = state.device.volume(cid, out).ok()?;
            Some((cid, out, v * crate::control_room::held_share(state, cid, out)))
        })
        .collect();
    let (mut scene, fx_plan) = crate::fx::prepare_scene(state, scene);
    let now = Instant::now();
    let db = |v: f32| 20.0 * v.max(1e-6).log10();
    let rises = |was: f32, to: f32| db(to) > db(was) + RAMP_OVER_DB as f32;
    // What the scene raises by more than `RAMP_OVER_DB` goes to the card at
    // its old level and glides up from there, as Recall's does (the
    // reviewer, 2026-11-04: an undo or a snapshot put a quiet output back
    // up at once). Capped in the scene before it's written: written at the
    // scene's level and walked back after, the card held the loud level in
    // between (OpenCode's job 9).
    // A level muted now that the scene unmutes plays from silence, not its
    // kept level (the level audit: mute Main, Ctrl+Z, and it came back at
    // full level in one write).
    let out_unmuting: Vec<bool> = (0..levels_before.len())
        .map(|ch| state.device.outputs().get(ch).is_some_and(|o| o.mute) && scene.outputs.get(ch).is_some_and(|o| !o.mute))
        .collect();
    let src_unmuting = |cid: ChannelId| match cid {
        ChannelId::Input(i) => state.device.inputs().get(i).is_some_and(|c| c.mute) && scene.inputs.get(i).is_some_and(|c| !c.mute),
        ChannelId::Playback(i) => state.device.playbacks().get(i).is_some_and(|c| c.mute) && scene.playbacks.get(i).is_some_and(|c| !c.mute),
        ChannelId::Output(_) => false,
    };
    let sends_before: Vec<(ChannelId, usize, f32)> = sends_before.into_iter().map(|(c, o, v)| (c, o, if src_unmuting(c) { 0.0 } else { v })).collect();
    let mut out_glides = Vec::new();
    for (ch, &was) in levels_before.iter().enumerate() {
        let was = if out_unmuting.get(ch).copied().unwrap_or(false) { 0.0 } else { was };
        if let Some(o) = scene.outputs.get_mut(ch) {
            if rises(was, o.volume) {
                out_glides.push((ch, was, o.volume));
                o.volume = was;
            }
        }
    }
    // A send the scene raises: that channel alone.
    let mut send_glides = Vec::new();
    for &(cid, out, was) in &sends_before {
        let slot = match cid {
            ChannelId::Input(i) => scene.inputs.get_mut(i).and_then(|c| c.volumes.get_mut(out)),
            ChannelId::Playback(i) => scene.playbacks.get_mut(i).and_then(|c| c.volumes.get_mut(out)),
            ChannelId::Output(_) => None,
        };
        if let Some(v) = slot {
            if rises(was, *v) {
                send_glides.push((cid, out, was, *v));
                *v = was;
            }
        }
    }
    // A gain the scene raises. A linked pair's gain is one: decided for
    // the pair, both sides capped, its first side carrying the ramp to the
    // higher of the two (Qwen's review: a second side that rose alone was
    // capped and never raised).
    let mut gain_glides = Vec::new();
    let mut idx = 0;
    while idx < before.len() {
        let linked = idx % 2 == 0 && idx + 1 < before.len() && state.device.input_pair_linked(idx / 2);
        let sides: Vec<usize> = if linked { vec![idx, idx + 1] } else { vec![idx] };
        let mut ramp: Option<(u32, u32)> = None;
        for &i in &sides {
            let (Some(was), Some(c)) = (before[i], scene.inputs.get_mut(i)) else {
                continue;
            };
            let Some(to) = c.gain else {
                continue;
            };
            if to > was + RAMP_OVER_DB {
                c.gain = Some(was);
                ramp = Some(ramp.map_or((was, to), |(w, t)| (w.min(was), t.max(to))));
            }
        }
        if let Some((was, to)) = ramp {
            gain_glides.push((idx, was, to));
            if linked {
                // Both sides start where the ramp does.
                for &i in &sides {
                    if let Some(c) = scene.inputs.get_mut(i) {
                        c.gain = Some(was);
                    }
                }
            }
        }
        idx += sides.len();
    }
    state.device.apply_scene(&scene)?;
    // A scene's glides are its own, not PAD off's rise (job 56).
    state.pad_rise = None;
    // Only once the scene is in: a refused one leaves the glides under way,
    // a Dim let go just before among them (`release_holding`), to finish.
    state.gain_ramps.clear();
    state.level_ramps.clear();
    state.fader_glides.clear();
    // Every cell is written: the glides below take over from the eases.
    crate::control_room::drop_easing(state);
    crate::fx::finish_scene(state, fx_plan, now);
    for (ch, was, to) in out_glides {
        state.level_ramps.insert(ch, (db(was).max(-60.0), db(to), now));
    }
    for (cid, out, was, to) in send_glides {
        // Written as a copy is: a scene coming back is no edit of that mix,
        // so its steps end no mirror (Undo put one back and its own glide
        // ended it on the next tick) and drag no mirror's target along.
        state.fader_glides.insert((cid, out), FaderGlide { from_db: db(was).max(-60.0), to_db: db(to), to, since: now, via: GlideVia::Copied });
    }
    for (idx, was, to) in gain_glides {
        state.gain_ramps.insert(idx, (was, to, now));
    }
    // LOOP never comes on from a recalled mix (`Scene::safe_outputs`): said,
    // so a stream's or recording's mix doesn't go quiet unexplained (the
    // second security review). A caller with a notice of its own adds the
    // sentence to it (`loop_held_note`), so it isn't covered up. The clock
    // isn't said: its names differ between drivers, and a kept clock is
    // no hazard.
    let held_loop = (0..state.device.output_pair_count())
        .any(|p| scene.outputs.get(p * 2).is_some_and(|o| o.loopback) && !state.device.outputs().get(p * 2).is_some_and(|o| o.loopback));
    state.loop_held_note = held_loop.then(|| "LOOP stays off: a recalled mix never switches it on. Press LOOP twice on the output to switch it on.".to_string());
    if let Some(note) = &state.loop_held_note {
        state.notice = Some((note.clone(), now));
    }
    Ok(())
}

/// The longest quit waits for the glides below: the Control Room's eases
/// take 500 ms.
const QUIT_GLIDE_MAX: Duration = Duration::from_millis(800);

/// Quitting with an override on (Dim, Talkback, a solo, the Cue): let go
/// held, as a scene does, and run the glides for real before the window
/// goes, so the unit isn't left with a level put back in one write (no tick
/// runs after a quit; OpenCode's job 46: Main back 40 dB at once). Nothing
/// held, nothing gliding: no wait at all. Whatever hasn't landed by
/// `QUIT_GLIDE_MAX` lands then (`release`), so nothing stays part-way.
/// `pause` is the real wait (`std::thread::sleep`); tests pass none.
pub(crate) fn let_go_before_quit(state: &mut TuxMix, pause: fn(Duration)) {
    let start = Instant::now();
    crate::control_room::release_holding(state, start);
    let busy = |state: &TuxMix| {
        crate::control_room::is_easing(state)
            || !state.level_ramps.is_empty()
            || !state.fader_glides.is_empty()
            || !state.gain_ramps.is_empty()
            || !state.fx_return_ramps.is_empty()
    };
    let step = Duration::from_millis(20);
    let mut at = start;
    while busy(state) && at.duration_since(start) < QUIT_GLIDE_MAX {
        pause(step);
        at += step;
        crate::control_room::step_easing(state, at);
        step_level_ramps(state, at);
        step_fader_glides(state, at);
        step_gain_ramps(state, at);
        crate::fx::step_return_ramps(state, at);
    }
    crate::control_room::release(state);
}

/// Each output that now stands more than `RAMP_OVER_DB` above where it
/// was (`before`, the device's levels earlier) goes back there and glides
/// up, as a scene's rises do. For changes made in one go that don't pass
/// through a scene (a Total Reset letting go of Dim; the local Qwen's
/// review, 2026-11-12).
pub(crate) fn glide_outputs_up_from(state: &mut TuxMix, before: &[f32]) {
    let db = |v: f32| 20.0 * v.max(1e-6).log10();
    let now = Instant::now();
    for (ch, &was) in before.iter().enumerate() {
        let Some(to) = state.device.outputs().get(ch).map(|o| o.volume) else { continue };
        if db(to) > db(was) + RAMP_OVER_DB as f32 {
            write_output_volume(state, ch, was);
            state.level_ramps.insert(ch, (db(was).max(-60.0), db(to), now));
        }
    }
}

/// Output levels on their way up after Recall raised them by more than
/// `RAMP_OVER_DB` (the reviewer: Recall put up to +6 dB on Main at once):
/// output channel, from and to (dB), since. Stepped on the tick
/// (`step_level_ramps`); a hand on that fader, Dim or any other Control
/// Room key stops them.
pub(crate) fn step_level_ramps(state: &mut TuxMix, now: Instant) {
    let ramps: Vec<(usize, (f32, f32, Instant))> = state.level_ramps.iter().map(|(&c, &r)| (c, r)).collect();
    let prev = ramp_step_clock(state, RampKind::Level, now, !ramps.is_empty());
    for (ch, (from_db, to_db, since)) in ramps {
        let (t, since) = capped_share(since, prev, now, RAMP_FOR, to_db - from_db);
        state.level_ramps.insert(ch, (from_db, to_db, since));
        let db = from_db + (to_db - from_db) * t;
        write_output_volume(state, ch, 10f32.powf(db / 20.0));
        if t >= 1.0 {
            state.level_ramps.remove(&ch);
        }
    }
}

/// How a gliding fader's steps reach the mix: as the gesture that started
/// it would have set it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum GlideVia {
    /// The strip alone (a double-click's reset).
    Strip,
    /// With its fader group and Trim Gains (a click on the lane; the
    /// Matrix in stereo).
    Grouped,
    /// One channel of a pair (the Matrix in Mono Mode).
    OneChannel,
    /// A send pasted or mirrored (`mixops`): no mix edit, so no mirror ends.
    Copied,
    /// A fader-group member following its lead (issue #38): the strip
    /// alone, each step handed to its Trim Gains mixes as its own step.
    Member,
    /// `Grouped`, its own Trim Gains left alone: a glide from silence
    /// (`step_fader_glides`).
    GroupedNoTrim,
}

/// A fader gliding up: from and to in dB, since, and how it is set; `to`
/// the level it lands on exactly (the dB's round trip lands a hair off:
/// 0.49999997 for 0.5).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct FaderGlide {
    pub from_db: f32,
    pub to_db: f32,
    pub to: f32,
    pub since: Instant,
    pub via: GlideVia,
}

/// The level a strip's fader shows in mix `out`: an output's own level
/// (the user's, under any Dim), or a send.
fn fader_level(state: &TuxMix, cid: ChannelId, out: usize) -> f32 {
    match cid {
        ChannelId::Output(ch) => crate::control_room::user_output_level(state, ch),
        _ => state.device.volume(cid, out).unwrap_or(0.0),
    }
}

/// One channel's send, whatever its pair's link: the device's own
/// per-channel write, past the pair handling of `set_*_volume` (the
/// Matrix in Mono Mode).
/// Links a source pair (`left`, an input or playback's left channel) the
/// gentle way: the device copies the left side's levels and mute onto the
/// right, held off the card (`hold_card`), then the right side's cells are
/// written by Audra: where the link raises one by more than `RAMP_OVER_DB`
/// (from silence if the right side was muted), at its old level, gliding
/// up (the level audit: the copy reached the card loud, then was walked
/// back; AN1→2, a mic preset's stereo and Reset Mix's "All stereo" never
/// walked it back at all).
pub(crate) fn link_sources_gently(state: &mut TuxMix, left: ChannelId) -> Result<(), tuxmix_core::Error> {
    let (r, pair) = match left {
        ChannelId::Input(i) => (ChannelId::Input(i | 1), i / 2),
        ChannelId::Playback(i) => (ChannelId::Playback(i | 1), i / 2),
        ChannelId::Output(_) => return Ok(()),
    };
    let muted = |state: &TuxMix, c: ChannelId| match c {
        ChannelId::Input(i) => state.device.inputs().get(i).is_some_and(|ch| ch.mute),
        ChannelId::Playback(i) => state.device.playbacks().get(i).is_some_and(|ch| ch.mute),
        ChannelId::Output(_) => false,
    };
    let l = match left {
        ChannelId::Input(i) => ChannelId::Input(i & !1),
        ChannelId::Playback(i) => ChannelId::Playback(i & !1),
        c => c,
    };
    let unmuting = muted(state, r) && !muted(state, l);
    let pairs = state.device.output_pair_count();
    let before: Vec<f32> = (0..pairs).map(|o| if unmuting { 0.0 } else { fader_level(state, r, o) }).collect();
    state.device.hold_card(true);
    let done = match left {
        ChannelId::Input(_) => state.device.set_input_pair_linked(pair, true),
        _ => state.device.set_playback_linked(pair, true),
    };
    state.device.hold_card(false);
    // The left side's cells too: the link set the pair's pan in the model
    // alone under the hold (the advisor).
    for out in 0..pairs {
        let v = state.device.volume(l, out).unwrap_or(0.0);
        let _ = write_send(state, out, |d| d.set_volume(l, out, v));
    }
    let db = |v: f32| 20.0 * v.max(1e-6).log10();
    let now = Instant::now();
    for (out, &old) in before.iter().enumerate() {
        let new = fader_level(state, r, out);
        if db(new) > db(old) + RAMP_OVER_DB as f32 {
            let _ = write_send(state, out, |d| d.set_volume(r, out, old));
            state.fader_glides.insert((r, out), FaderGlide { from_db: db(old).max(-60.0), to_db: db(new), to: new, since: now, via: GlideVia::OneChannel });
        } else {
            let _ = write_send(state, out, |d| d.set_volume(r, out, new));
        }
    }
    crate::control_room::after_mix_change(state, None);
    done
}

fn set_one_channel_volume(state: &mut TuxMix, cid: ChannelId, out: usize, v: f32) {
    if let Err(e) = write_send(state, out, |d| d.set_volume(cid, out, v)) {
        fail(state, "set_volume", &e);
    }
    notify_osc(state, OscOutbound::Volume(cid, out, v));
    crate::control_room::after_mix_change(state, Some(out));
    crate::mixops::after_send_edit(state, cid, out);
}

fn write_level(state: &mut TuxMix, cid: ChannelId, out: usize, v: f32, via: GlideVia) {
    match via {
        GlideVia::Strip => {
            set_channel_volume(state, cid, out, v);
            notify_osc(state, OscOutbound::Volume(cid, out, v));
        }
        GlideVia::Grouped => apply_grouped_volume(state, cid, out, v),
        GlideVia::GroupedNoTrim => apply_grouped_volume_trimmed(state, cid, out, v, false),
        GlideVia::Member => {
            let cur = state.device.volume(cid, out).unwrap_or(0.0);
            set_channel_volume(state, cid, out, v);
            notify_osc(state, OscOutbound::Volume(cid, out, v));
            trim_other_routings(state, cid, out, cur, vol_to_db(v) - vol_to_db(cur));
        }
        GlideVia::OneChannel => set_one_channel_volume(state, cid, out, v),
        // A pasted or mirrored send: written as a copy is, not as an edit of
        // that mix (which would end its mirror: the advisor).
        GlideVia::Copied => {
            if let Err(e) = write_send(state, out, |d| d.set_volume(cid, out, v)) {
                fail(state, "set_volume", &e);
            }
            notify_osc(state, OscOutbound::Volume(cid, out, v));
            crate::control_room::after_mix_change(state, Some(out));
        }
    }
}

/// A level set by one click (a double-click's reset, a click on the lane,
/// the Matrix's Ctrl+click): lowered or raised a little, it lands at once;
/// raised by more than `RAMP_OVER_DB`, it glides up over `RAMP_FOR`, as a
/// mic preset's gain does (the critique, 2026-11-05: a double-click on a
/// Main at -30 dB put 0 dB in the speakers in one step). A hand on the
/// fader, Undo or a snapshot stops it.
pub(crate) fn set_level_gently(state: &mut TuxMix, cid: ChannelId, out: usize, to: f32, via: GlideVia) {
    let from = fader_level(state, cid, out);
    let db = |v: f32| 20.0 * v.max(1e-6).log10();
    let rises = db(to) > db(from) + RAMP_OVER_DB as f32;
    // A glide already on its way there takes the new target and keeps its
    // clock (OpenCode's job 37: a surface's fader sends a position every
    // few milliseconds, and each one started the glide again from its first
    // share, so the level crept up a second behind the hand). Only a target
    // near the old one: the level then moves no more than 6 dB for it.
    // Only for a remote's stream of moves, and only further up: a hand on
    // the screen takes the level from its glide, as ever, and a lower
    // target would pull the glide's line down with it (OpenCode's job 38).
    if rises && state.from_remote {
        if let Some(g) = state.fader_glides.get_mut(&(cid, out)) {
            if g.via == via && db(to) >= g.to_db && db(to) - g.to_db <= RAMP_OVER_DB as f32 {
                g.to = to;
                g.to_db = db(to);
                return;
            }
        }
    }
    stop_fader_glides(state, cid);
    if rises {
        let glide = FaderGlide { from_db: db(from).max(-60.0), to_db: db(to), to, since: Instant::now(), via };
        state.fader_glides.insert((cid, out), glide);
    } else {
        write_level(state, cid, out, to, via);
    }
}

/// How long a remote's burst counts on after its last move: a quiet
/// second ends it.
const REMOTE_BURST: Duration = Duration::from_secs(1);


/// A remote's (OSC) level: as `set_level_gently`, and a rise of more than
/// `RAMP_OVER_DB` over where its burst began glides too, so many small
/// steps can't add up to a loud jump. While it glides a new target near
/// the old one carries on the glide; a far one starts it again from where
/// the level is now, so no write jumps.
fn set_remote_level(state: &mut TuxMix, cid: ChannelId, out: usize, to: f32, via: GlideVia) {
    let db = |v: f32| 20.0 * v.max(1e-6).log10();
    let from = fader_level(state, cid, out);
    let now = Instant::now();
    if now.duration_since(state.remote_rise.1) > REMOTE_BURST {
        state.remote_rise.0 = 0.0;
    }
    state.remote_rise.1 = now;
    // A move down is never the hazard: it lands, and spends nothing.
    if db(to) <= db(from) {
        set_level_gently(state, cid, out, to, via);
        return;
    }
    let rise = db(to) - db(from).max(-60.0);
    if state.remote_rise.0 + rise > RAMP_OVER_DB as f32 {
        if let Some(g) = state.fader_glides.get_mut(&(cid, out)) {
            if g.via == via && db(to) >= g.to_db && db(to) - g.to_db <= RAMP_OVER_DB as f32 {
                g.to = to;
                g.to_db = db(to);
                return;
            }
        }
        stop_fader_glides(state, cid);
        let glide = FaderGlide { from_db: db(from).max(-60.0), to_db: db(to), to, since: now, via };
        state.fader_glides.insert((cid, out), glide);
        return;
    }
    state.remote_rise.0 += rise;
    set_level_gently(state, cid, out, to, via);
}

/// Adds the last recall's "LOOP stays off" sentence to the notice up now.
pub(crate) fn add_loop_held_note(state: &mut TuxMix) {
    if let (Some(note), Some((text, _))) = (state.loop_held_note.take(), state.notice.as_mut()) {
        if !text.contains(&note) {
            text.push(' ');
            text.push_str(&note);
        }
    }
}

/// A ready-made setup's level (`setups`): as `set_level_gently`, a rise
/// gliding up, but without stopping the strip's other glides, since one
/// setup raises a strip in two mixes at once (the Phones and a recording
/// mix) and the second write cancelled the first.
///
/// The strip alone (`GlideVia::Strip`, its pair with it): a setup sets the
/// levels its card names and no other. By the grouped route, with Trim
/// Gains on, the computer raised in the Phones came up as far in the
/// speakers, and the mic's fader group travelled with it (the safety audit
/// of 2026-11-17).
pub(crate) fn setup_level(state: &mut TuxMix, cid: ChannelId, out: usize, to: f32) {
    level_gently_keeping_glides(state, cid, out, to, GlideVia::Strip);
}

/// `setup_level` by the route `via`: Reset Mix sets each channel on its
/// own (`GlideVia::OneChannel`), a setup a strip with its group.
pub(crate) fn level_gently_keeping_glides(state: &mut TuxMix, cid: ChannelId, out: usize, to: f32, via: GlideVia) {
    let from = fader_level(state, cid, out);
    let db = |v: f32| 20.0 * v.max(1e-6).log10();
    state.fader_glides.remove(&(cid, out));
    if db(to) > db(from) + RAMP_OVER_DB as f32 {
        let glide = FaderGlide { from_db: db(from).max(-60.0), to_db: db(to), to, since: Instant::now(), via };
        state.fader_glides.insert((cid, out), glide);
    } else {
        write_level(state, cid, out, to, via);
    }
}

/// A hand on strip `cid` (in any mix) takes it from its glide.
fn stop_fader_glides(state: &mut TuxMix, cid: ChannelId) {
    state.fader_glides.retain(|(c, _), _| *c != cid);
}

/// What a reset sets strip `cid` to: `to`, except that an output listened
/// on (the Main, Main B, the Phones) is never turned up by one; it stays,
/// and a notice says why and how (2026-11-05, the owner's choice; as Reset
/// Mix already does).
fn reset_target(state: &mut TuxMix, cid: ChannelId, out: usize, to: f32) -> f32 {
    let ChannelId::Output(ch) = cid else {
        return to;
    };
    if !crate::control_room::listened_on(state, ch) {
        return to;
    }
    let now = fader_level(state, cid, out);
    if to > now + 1e-6 {
        let name = strip_params(state, cid, out).name;
        state.notice = Some((
            format!(
                "{name} stays at {} dB: a double-click never turns up what you listen on. Drag it up.",
                db_number(now)
            ),
            Instant::now(),
        ));
        now
    } else {
        to
    }
}

/// Tests: steps a glide from `from` to `to` a tick (30 ms) at a time, as
/// the app's tick does; one jump would be held to a regular step
/// (`RAMP_STEP_MAX`).
#[cfg(test)]
pub(crate) fn tick_through(state: &mut TuxMix, step: fn(&mut TuxMix, Instant), from: Instant, to: Instant) {
    let mut at = from;
    loop {
        // 25 ms: under the cap's share of a 300 ms glide, so `to` is where
        // the clock says it is.
        at = (at + Duration::from_millis(25)).min(to);
        step(state, at);
        if at >= to {
            break;
        }
    }
}

/// Takes each gliding fader its next step toward its level (on the tick).
/// Tests: every glide and ramp under way run to its end, as a scene's
/// rises glide now (issue #22).
#[cfg(test)]
pub(crate) fn settle_glides(state: &mut TuxMix) {
    // A step every 30 ms, as the tick takes them: a step no glide may
    // outrun (`RAMP_STEP_MAX`).
    let base = Instant::now();
    for i in 1..=60u64 {
        let at = base + Duration::from_millis(25 * i);
        step_fader_glides(state, at);
        step_level_ramps(state, at);
        step_gain_ramps(state, at);
        crate::fx::step_return_ramps(state, at);
        if state.fader_glides.is_empty() && state.level_ramps.is_empty() && state.gain_ramps.is_empty() && state.fx_return_ramps.is_empty() {
            break;
        }
    }
    crate::control_room::settle_easing(state);
}

pub(crate) fn step_fader_glides(state: &mut TuxMix, now: Instant) {
    let glides: Vec<((ChannelId, usize), FaderGlide)> = state.fader_glides.iter().map(|(&k, &g)| (k, g)).collect();
    let prev = ramp_step_clock(state, RampKind::Fader, now, !glides.is_empty());
    for ((cid, out), mut g) in glides {
        // Replaced or ended by an earlier glide's write this tick (a lead's
        // step retargets its members): that newer one stands, never this
        // copy (the reviewer: the old copy was put back and written).
        if state.fader_glides.get(&(cid, out)) != Some(&g) {
            continue;
        }
        let (t, since) = capped_share(g.since, prev, now, RAMP_FOR, g.to_db - g.from_db);
        g.since = since;
        state.fader_glides.insert((cid, out), g);
        let db = g.from_db + (g.to_db - g.from_db) * t;
        let mut v = if t >= 1.0 { g.to } else { 10f32.powf(db / 20.0) };
        // Never more than RAMP_STEP_DB over what the fader has now, however
        // the glide's target moved (the security review: a remote raised a
        // glide's target 60 dB in one frame, and the next tick, the glide
        // nearly done, wrote 58 dB at once). Capped, the glide starts again
        // from the capped step towards the same target.
        let now_db = 20.0 * fader_level(state, cid, out).max(1e-6).log10();
        let wrote_db = 20.0 * v.max(1e-6).log10();
        if wrote_db > now_db.max(-60.0) + RAMP_STEP_DB {
            let capped = now_db.max(-60.0) + RAMP_STEP_DB;
            v = 10f32.powf(capped / 20.0);
            g.from_db = capped;
            g.since = now;
            state.fader_glides.insert((cid, out), g);
            let via = match g.via {
                GlideVia::Member if now_db <= -59.99 => GlideVia::Strip,
                GlideVia::Grouped if now_db <= -59.99 => GlideVia::GroupedNoTrim,
                via => via,
            };
            write_level(state, cid, out, v, via);
            continue;
        }
        // From silence, its steps hand no Trim Gains step on: a move from
        // -inf trims nothing when it's one write, so not when it glides
        // (the reviewer: the other mixes came up the whole glide).
        let via = match g.via {
            GlideVia::Member if g.from_db <= -59.99 => GlideVia::Strip,
            GlideVia::Grouped if g.from_db <= -59.99 => GlideVia::GroupedNoTrim,
            via => via,
        };
        write_level(state, cid, out, v, via);
        if t >= 1.0 {
            state.fader_glides.remove(&(cid, out));
        }
    }
}

/// Marks the inputs whose preamp gain differs from `before` (what the
/// device held before its poll) so their readouts flash: a change the poll
/// brought in came from outside Audra (2026-11-03, the owner turned the
/// unit's wheel and saw nothing move). Animations off: no flash.
pub(crate) fn note_outside_gains(state: &mut TuxMix, before: &[Option<u32>]) {
    let now = Instant::now();
    let changed: Vec<usize> = state
        .device
        .inputs()
        .iter()
        .enumerate()
        .filter(|(i, c)| matches!(before.get(*i), Some(Some(old)) if c.gain.is_some_and(|g| g != *old)))
        .map(|(i, _)| i)
        .collect();
    // A turn of the unit's wheel is no Undo step: the notice's key would now
    // take it back with the notice's change, so the key goes.
    if !changed.is_empty() {
        state.notice_undo = None;
    state.undo_tip_kept = None;
    }
    if !state.animations {
        return;
    }
    for i in changed {
        state.gain_flash.insert(i, now);
    }
}

/// How long a first click on an unlit 48V waits for the second.
pub(crate) const PHANTOM_ARM_FOR: Duration = Duration::from_secs(4);
/// How long a 48V armed by a mic preset waits for its confirming click.
pub(crate) const PRESET_ARM_FOR: Duration = Duration::from_secs(12);

/// Starts the FX loop when Reverb or Echo turns on, hands it new settings,
/// and stops it when both are off. A real unit only: the mock has no FX
/// channels to loop. Stopping waits for the loop's threads, so it happens
/// off the UI thread; the children die with their pipes either way.
pub(crate) fn sync_fx_loop(state: &mut TuxMix) {
    let wanted = !state.device.is_mock() && state.fx.any_on();
    match (&state.fx_loop, wanted) {
        (None, true) => state.fx_loop = Some(crate::fx_loop::FxLoop::start(state.fx)),
        (Some(l), true) => l.set(state.fx),
        (Some(_), false) => {
            if let Some(l) = state.fx_loop.take() {
                std::thread::spawn(move || drop(l));
            }
            state.fx_state = None;
        }
        (None, false) => {}
    }
}

/// On air (`sounds::on_air`): Rec recording, an app recording from
/// Voice, or a mic open into speakers that are up.
pub(crate) fn on_air(state: &TuxMix) -> bool {
    state.recorder.is_some() || state.dyn_heard == Some(true) || crate::sidebar::open_mic_shown(state).is_some()
}

/// Clears every arm whose wait has run out (48V?, LOOP?, a reset, a
/// workspace load); whether there was one.
fn disarm_expired(state: &mut TuxMix) -> bool {
    use crate::resetmix::ARM_FOR;
    let mut any = false;
    let mut out = |at: Instant, wait: Duration| {
        let gone = at.elapsed() >= wait;
        any |= gone;
        gone
    };
    if state.phantom_armed.is_some_and(|(_, at)| out(at, state.phantom_arm_for)) {
        state.phantom_armed = None;
    }
    if state.loop_armed.is_some_and(|(_, at)| out(at, PHANTOM_ARM_FOR)) {
        state.loop_armed = None;
    }
    if state.reset_armed.is_some_and(|(_, at)| out(at, ARM_FOR)) {
        state.reset_armed = None;
    }
    if state.workspace_armed.is_some_and(|(_, at)| out(at, ARM_FOR)) {
        state.workspace_armed = None;
    }
    if state.mic_preset_remove_armed.is_some_and(|(_, at)| out(at, ARM_FOR)) {
        state.mic_preset_remove_armed = None;
    }
    if state.link_armed.is_some_and(|at| out(at, PRESET_ARM_FOR)) {
        state.link_armed = None;
    }
    // Voice's two waits too: Reset to Natural, and an output's ON off while
    // apps play there. Left set, the wait ended silently (the scout). Heard
    // only while a Voice panel shows its "press again" (OpenCode's job 34:
    // closed, the click spoke of something no longer on screen).
    let ran_out = |at: Instant, wait: Duration| at.elapsed() >= wait;
    if let Some(((output, left), _)) = state.dyn_reset_armed.filter(|&(_, at)| ran_out(at, crate::dynamics_panel::RESET_ARM_FOR)) {
        state.dyn_reset_armed = None;
        any |= crate::dynamics_panel::panel_shown(state, output, left);
    }
    if let Some((left, _)) = state.dyn_off_armed.filter(|&(_, at)| ran_out(at, crate::dynamics_panel::OFF_ARM_FOR)) {
        state.dyn_off_armed = None;
        any |= crate::dynamics_panel::panel_shown(state, true, left);
    }
    // Nothing left to warn about (AN2 changed meanwhile): the arm goes, so
    // its row never reads "Press again:" with nothing after it.
    if state.link_armed.is_some() && link_an12_changes(state).is_empty() {
        state.link_armed = None;
        any = true;
    }
    any
}

/// Whether output channel `i`'s LOOP is armed (clicked once, waiting).
pub(crate) fn loop_armed(state: &TuxMix, i: usize) -> bool {
    state.loop_armed.is_some_and(|(o, at)| o == i && at.elapsed() < PHANTOM_ARM_FOR)
}

/// The input pair an output pair's loopback records over (manual 23.6:
/// each output pair's record bus is the input pair of the same number),
/// as the strip names it ("AN1/2", "IN3/4").
pub(crate) fn looped_input_name(state: &TuxMix, out_ch: usize) -> String {
    let pair = if state.device.outputs_one_per_pair() { out_ch } else { out_ch / 2 };
    short_label(&strip_display_name(state, ChannelId::Input(pair * 2))).to_string()
}

/// Voice is on for Quick setup's mic and the mix to your apps carries the
/// computer alone: the stream takes the voice from Voice (Stream with Voice).
fn stream_takes_voice(state: &TuxMix) -> bool {
    let cid = state.quick_channel;
    crate::dynamics_panel::power_of(state, cid)
        && (0..state.device.output_pair_count()).any(|p| {
            input_looped(state, p * 2) && state.device.volume(cid, p).unwrap_or(0.0) <= 0.0 && state.device.volume(ChannelId::Playback(0), p).unwrap_or(0.0) > 0.0
        })
}

/// Voice just went off for `cid` while the mix to your apps carries the
/// computer alone (Stream with Voice on): the plain mic goes back into it,
/// so the stream never goes voiceless (critique #108 A P2-1).
fn voice_off_keeps_the_stream(state: &mut TuxMix, cid: ChannelId, was_on: bool) {
    if !was_on || crate::dynamics_panel::power_of(state, cid) || !matches!(cid, ChannelId::Input(_)) {
        return;
    }
    let stream = (0..state.device.output_pair_count()).find(|&p| {
        input_looped(state, p * 2)
            && state.device.volume(cid, p).unwrap_or(0.0) <= 0.0
            && state.device.volume(ChannelId::Playback(0), p).unwrap_or(0.0) > 0.0
    });
    if let Some(p) = stream {
        set_level_gently(state, cid, p, 10f32.powf(-3.0 / 20.0), GlideVia::OneChannel);
        let name = short_label(&strip_display_name(state, cid)).to_string();
        state.notice = Some((format!("Voice is off: {name} is back in the mix to your apps at \u{2212}3 dB, so your stream still hears you."), Instant::now()));
    }
}

/// Each plain mic (Voice off) in a mix to your apps that carries the
/// computer too: the stream hears that voice (see `say_stream_lost_voice`).
pub(crate) fn plain_voices_in_streams(state: &TuxMix) -> Vec<(ChannelId, usize)> {
    let mut found = Vec::new();
    for (i, input) in state.device.inputs().iter().enumerate() {
        let cid = ChannelId::Input(i);
        if input.channel_type != tuxmix_core::ChannelType::Mic || crate::dynamics_panel::power_of(state, cid) {
            continue;
        }
        for p in 0..state.device.output_pair_count() {
            if input_looped(state, p * 2)
                && state.device.volume(cid, p).unwrap_or(0.0) > 0.0
                && state.device.volume(ChannelId::Playback(0), p).unwrap_or(0.0) > 0.0
            {
                found.push((cid, p));
            }
        }
    }
    found
}

/// After Undo, Redo or a recall: a mic `before` had in a mix to your apps,
/// now out of it with the computer still there and Voice off, so a stream
/// from it lost the voice. Said, not overridden: the step is the user's
/// (critique #111 A P2-2, both reviewers: Voice off put the mic back, and
/// Undo took it out again with nothing said).
pub(crate) fn say_stream_lost_voice(state: &mut TuxMix, before: &[(ChannelId, usize)], by: &str, back: &str) {
    let lost = before.iter().find(|&&(cid, p)| {
        !crate::dynamics_panel::power_of(state, cid)
            && input_looped(state, p * 2)
            && state.device.volume(cid, p).unwrap_or(0.0) <= 0.0
            && state.device.volume(ChannelId::Playback(0), p).unwrap_or(0.0) > 0.0
    });
    if let Some(&(cid, _)) = lost {
        let name = short_label(&strip_display_name(state, cid)).to_string();
        let at = Instant::now();
        state.notice = Some((format!("{by} took {name} out of the mix to your apps, and Voice is off: your stream won\u{2019}t hear you. {back}"), at));
        state.notice_sticky_at = Some(at);
    }
}

/// A looped-back output (the mix to your apps) that carries `cid` itself,
/// the plain mic, if any: then a stream from it has the voice unshaped.
pub(crate) fn plain_mic_looped(state: &TuxMix, cid: ChannelId) -> Option<usize> {
    (0..state.device.output_pair_count()).find(|&p| input_looped(state, p * 2) && state.device.volume(cid, p).unwrap_or(0.0) > 0.0)
}

/// Whether input `i`'s recording is replaced by an output's loopback.
pub(crate) fn input_looped(state: &TuxMix, i: usize) -> bool {
    let pair = i / 2;
    let out_ch = if state.device.outputs_one_per_pair() { pair } else { pair * 2 };
    state.device.outputs().get(out_ch).is_some_and(|o| o.loopback)
}

/// Whether input `idx`'s 48V is armed (clicked once, waiting).
/// What linking AN1/2 now would change on AN2, said in words: the link
/// copies AN1's 48V, PAD and mute onto AN2 (`align_pair_preamp`,
/// `align_pair`). 48V coming on asks only with the 48V confirm on; a PAD
/// coming off (11 dB louder) and an unmute always.
pub(crate) fn link_an12_changes(state: &TuxMix) -> Vec<&'static str> {
    let mut changes = Vec::new();
    let ins = state.device.inputs();
    let (Some(a), Some(b)) = (ins.first(), ins.get(1)) else {
        return changes;
    };
    if state.device.input_pair_linked(0) || a.gain_max.is_none() || b.gain_max.is_none() {
        return changes;
    }
    if state.confirm_48v && a.phantom && !b.phantom {
        changes.push("48V on AN2");
    }
    if !a.pad && b.pad {
        changes.push("AN2's PAD off (+11 dB)");
    }
    if !a.mute && b.mute {
        changes.push("AN2 unmuted");
    }
    changes
}

/// Whether AN1/2's link waits for its second press (`Message::LinkArm`),
/// as long as a mic preset's 48V does: its notice takes a while to read.
pub(crate) fn link_armed(state: &TuxMix) -> bool {
    state.link_armed.is_some_and(|at| at.elapsed() < PRESET_ARM_FOR)
}

pub(crate) fn phantom_armed(state: &TuxMix, idx: usize) -> bool {
    state
        .phantom_armed
        .is_some_and(|(i, at)| i == idx && at.elapsed() < state.phantom_arm_for)
}

/// What a snapshot slot (1-based) is called: the user's name, else
/// "Snapshot n" (critique #5: "Mix n" beside "Now mixing Main 1/2" read as
/// an output mix; the files keep their "Mix n.json" names); "Snapshot" with
/// no slot.
pub(crate) fn snapshot_title(state: &TuxMix, slot: Option<usize>) -> String {
    match slot {
        Some(n) if (1..=8).contains(&n) => state.snapshot_names[n - 1]
            .clone()
            .unwrap_or_else(|| format!("Snapshot {n}")),
        _ => "Snapshot".to_string(),
    }
}

/// An undo step that stored over a snapshot (`TuxMix::undo_slots`): the
/// step's place on its stack, the slot (1-based), and what it held.
#[derive(Clone, Debug)]
pub struct SlotUndo {
    pub at: usize,
    pub slot: usize,
    pub scene: Option<Scene>,
}

/// An undo step that switched Reverb and Echo (`TuxMix::undo_fx`): the
/// step's index and the effects (reverb, echo) to put back with it.
#[derive(Clone, Copy, Debug)]
pub struct FxUndo {
    pub at: usize,
    pub fx: (bool, bool),
}

/// Takes back the undo step the message being handled opened, when it
/// turns out to change nothing (a setup that can't run, a My setup that
/// can't be read): Undo doesn't spend a press on it.
pub(crate) fn drop_opened_step(state: &mut TuxMix) {
    if state.opened_step && state.undo_stack.pop().is_some() {
        state.opened_step = false;
        let len = state.undo_stack.len();
        state.undo_mirrors.retain(|m| m.0 < len);
    }
}

/// Pushes an undo step, the stack held to its cap (the slot records
/// moving down with it) and the redo stack cleared.
fn push_undo(state: &mut TuxMix, scene: Scene) {
    // A newer step: the notice's Undo key would take back this one, not
    // what the notice said, so the key goes (its words stay).
    state.notice_undo = None;
    state.undo_tip_kept = None;
    // A step that isn't the setup's own: its card's Undo would take back
    // this one instead (the safety audit of 2026-11-17: a Store over a
    // slot, a click on an empty slot; neither counts as a mix change).
    if !state.setup_own_step {
        state.setup_fresh = false;
    }
    let mirrors = state.mirrors_before.clone().unwrap_or_else(|| state.mirrors.clone());
    state.undo_mirrors.push((state.undo_stack.len(), mirrors));
    state.undo_stack.push(scene);
    if state.undo_stack.len() > UNDO_STACK_CAP {
        state.undo_stack.remove(0);
        state.undo_mirrors.retain(|m| m.0 > 0);
        for m in &mut state.undo_mirrors {
            m.0 -= 1;
        }
        state.undo_slots.retain(|s| s.at > 0);
        for s in &mut state.undo_slots {
            s.at -= 1;
        }
        state.undo_fx.retain(|f| f.at > 0);
        for f in &mut state.undo_fx {
            f.at -= 1;
        }
    }
    state.redo_stack.clear();
    state.redo_slots.clear();
    state.redo_fx.clear();
    state.redo_mirrors.clear();
}

/// Reverb and Echo switched to `fx` (reverb, echo), each only if it differs.
fn set_fx_units(state: &mut TuxMix, fx: (bool, bool)) {
    for (unit, on) in [(crate::fx::Unit::Reverb, fx.0), (crate::fx::Unit::Echo, fx.1)] {
        if crate::fx::is_on(state, unit) != on {
            let _ = crate::fx::update(state, Message::FxOn(unit, on));
        }
    }
}

/// "Reverb and Echo on", "Reverb on and Echo off"...: what `fx` is, in words.
fn fx_units_words(fx: (bool, bool)) -> &'static str {
    match fx {
        (true, true) => "Reverb and Echo on",
        (false, false) => "Reverb and Echo off",
        (true, false) => "Reverb on, Echo off",
        (false, true) => "Echo on, Reverb off",
    }
}

/// What snapshot slot `n` (1-based) holds now.
fn slot_scene(state: &TuxMix, n: usize) -> Option<Scene> {
    if state.device.is_mock() {
        state.mock_snapshots.get(n - 1).cloned().flatten()
    } else {
        load_scene_file(&format!("Mix {n}"))
    }
}

/// Puts `scene` in snapshot slot `n` (1-based); an empty one only empties
/// the simulation's (a file left as it is).
fn write_slot(state: &mut TuxMix, n: usize, scene: Option<Scene>) -> Result<(), String> {
    let stored = scene.is_some();
    if state.device.is_mock() {
        if let Some(slot) = state.mock_snapshots.get_mut(n - 1) {
            *slot = scene;
        }
    } else if let Some(scene) = scene {
        save_scene_file(&format!("Mix {n}"), &scene)?;
    }
    if let Some(flag) = state.stored_snapshots.get_mut(n - 1) {
        *flag = stored;
    }
    Ok(())
}

/// Which "Mix n" files exist; none for the mock, which keeps its own in
/// memory (`mock_snapshots`).
fn stored_snapshot_slots(simulated: bool) -> [bool; 8] {
    std::array::from_fn(|i| {
        !simulated
            && crate::scenes::scenes_dir()
                .join(format!("Mix {}.json", i + 1))
                .exists()
    })
}

/// Swaps the no-device placeholder for the card that just showed up, and
/// sets up everything `new` sets up differently for real hardware: the
/// auto-saved mix, the playback meters from PipeWire, the snapshot files,
/// the audio engine. What was done in the demo goes with the mock.
fn adopt_device(state: &mut TuxMix, device: DeviceHandle) {
    log::info!("Device found");
    state.device = device;
    crate::workspaces::forget_demo_backup(state);
    state.control_room.dimmed_main = None;
    state.control_room.dim_easing = None;
    state.control_room.easing.clear();
    state.control_room.cue = None;
    state.control_room.talkback = false;
    state.control_room.ext_in = false;
    state.control_room.listenback = false;
    state.control_room.soloed.clear();
    state.control_room.solo_pair = None;
    state.control_room.pfl.clear();
    state.no_device = None;
    state.device_hint = None;
    state.connected = state.device.is_connected();
    if let Some(scene) = tuxmix_core::scene::load_auto_scene() {
        // As a start and a reconnect do: on USB the outputs come up from
        // silence (the level audit: a unit plugged in after a start with
        // none got the saved mix at full level in one write).
        let (done, rising) = restore_auto_scene_gently(&mut state.device, &scene);
        if let Err(e) = done {
            fail(state, "apply_scene", &e);
        }
        start_output_rises(state, &rising);
        crate::control_room::reapply(state);
    }
    state.device.sync_an12_link();
    state.input_meters = vec![MeterAnim::new(); state.device.inputs().len()];
    state.playback_meters = vec![MeterAnim::new(); state.device.playbacks().len()];
    state.output_meters = vec![MeterAnim::new(); state.device.outputs().len()];
    state.playback_tap = pw_meter::Tap::start_playback();
    state.fx_available = state.device.has_fx();
    state.playback_tap_channels = 0;
    state.stored_snapshots = stored_snapshot_slots(false);
    state.my_setup_stored = crate::scenes::scenes_dir().join("My setup.json").exists();
    state.mock_snapshots = Default::default();
    state.active_snapshot = None;
    state.snapshot_dirty = false;
    state.undo_stack.clear();
    state.redo_stack.clear();
    state.undo_slots.clear();
    state.redo_slots.clear();
    state.undo_fx.clear();
    state.redo_fx.clear();
    state.undo_mirrors.clear();
    state.redo_mirrors.clear();
    // As at launch: the file on disk is not a fresh write by another UI.
    state.last_saved_json = tuxmix_core::scene::read_auto_scene_raw();
    state.engine = None;
    state.card_stream = None;
    state.driver_floor = None;
    restore_engine(state);
}

/// The persisted subset of `state` (see `prefs.rs`).
pub fn prefs_of(state: &TuxMix) -> crate::prefs::Prefs {
    let mut labels: Vec<(ChannelId, String)> =
        state.labels.iter().map(|(c, l)| (*c, l.clone())).collect();
    // Stable order, so an unchanged state writes an unchanged file.
    labels.sort_by_key(|(c, _)| format!("{c:?}"));
    crate::prefs::Prefs {
        // Set in Audra settings → App (`launcher`).
        launcher_entry: state.launcher_entry_off.then_some(false),
        view: Some(state.view),
        sidebar_open: Some(state.sidebar_open),
        sidebar_width: Some(state.sidebar_width),
        two_row: None,
        row_mode: Some(state.row_mode),
        open_floor: Some(state.open_floor),
        mirrors: state.mirrors.clone(),
        // Only written once a slot is used.
        eq_presets: if state.eq_presets.iter().any(Option::is_some) {
            state.eq_presets.clone()
        } else {
            Vec::new()
        },
        mic_presets: state.mic_presets.clone(),
        startup_mic_preset: state.startup_mic_preset.clone(),
        ui_scale: Some(state.ui_scale),
        labels,
        show_original_names: state.show_original_names,
        window_size: state.window_size,
        // Only a choice to leave the default is worth writing down.
        keep_in_tray: (!state.keep_in_tray).then_some(false),
        tray_asked: state.tray_asked,
        tricks_found: state.tricks_found.clone(),
        shimmers_shown: state.shimmers_shown.clone(),
        tips_shown: state.tips_shown.clone(),
        tips_off: !state.tips,
        helper_cat_off: !state.helper_cat,
        milestones_off: !state.milestone_cards,
        small_wins_off: !state.small_wins,
        plain_names_off: !state.plain_names,
        fx: state.fx,
        fx_presets: state.fx_presets.clone(),
        fx_send_follow: state.fx_send_follow,
        fx_send_db: state.device.settings().fx_send_db,
        source_fx_send: state.device.settings().source_fx_send.clone(),
        milestones: state.milestones_seeded.then(|| state.milestones.clone()),
        milestones_all_on: state.milestones_all_on.clone(),
        guides_all_on: state.guides_all_on.clone(),
        celebration_sounds_off: !state.celebration_sounds,
        guides_done: (!state.guides_done.is_empty()).then(|| state.guides_done.clone()),
        autoset: (!state.autoset.is_empty()).then(|| state.autoset.iter().copied().collect()),
        dynamics_input: state.dyn_input,
        auto_tune: state.tune_on.then_some(true),
        noise_removal: (state.nr_level > 0).then_some(state.nr_level),
        low_delay: state.low_delay.then_some(true),
        dyn_more: state.dyn_more.then_some(true),
        dyn_fine_open: state.dyn_fine_open.then_some(true),
        quick_voice_skipped: state.quick_voice_skipped.then_some(true),
        d_hint_done: state.d_hint_done.then_some(true),
        de_esser: (state.deess_level > 0).then_some(state.deess_level),
        record_folder: state.record_folder.as_ref().map(|d| d.to_string_lossy().into_owned()),
        record_plain: false,
        record_no_reverb: !state.record_reverb,
        record_no_echo: !state.record_echo,
        dynamics: Some(state.dyn_params),
        dynamics_yours: state.dyn_yours.get(&(false, 0)).map(|y| y.params),
        dynamics_yours_extras: state.dyn_yours.get(&(false, 0)).and_then(|y| y.extras).map(|x| (x.noise, x.deess, x.tune)),
        dynamics_outputs: (!state.dyn_outs.is_empty())
            .then(|| state.dyn_outs.iter().map(|(&output, o)| crate::prefs::OutDynPref { output, on: o.on, params: o.params }).collect()),
        room_eq: (state.room_eq != crate::room_eq::fresh()).then_some(state.room_eq),
        open_mics_kept: (!state.open_mic_kept.is_empty()).then(|| {
            let mut v: Vec<(ChannelId, usize)> = state.open_mic_kept.iter().copied().collect();
            v.sort_by_key(|&(c, p)| (format!("{c:?}"), p));
            v
        }),
        // Kept as left (2026-11-06: every page closed reopened Snapshots).
        open_page: (state.sidebar_tab != Some(sidebar::Tab::default())).then(|| sidebar::page_name(state.sidebar_tab).to_string()),
        solo_exclusive: (!state.solo_exclusive).then_some(false),
        live_mode: state.control_room.live_mode.then_some(true),
        snapshot_keep: Some(state.snapshot_keep),
        hidden: {
            let mut v: Vec<ChannelId> = state.hidden.iter().copied().collect();
            v.sort_by_key(|c| format!("{c:?}"));
            v
        },
        hidden_remote: {
            let mut v: Vec<ChannelId> = state.hidden_remote.iter().copied().collect();
            v.sort_by_key(|c| format!("{c:?}"));
            v
        },
        snapshot_names: if state.snapshot_names.iter().any(Option::is_some) {
            state.snapshot_names.to_vec()
        } else {
            Vec::new()
        },
        snapshot_fx: if state.snapshot_fx.iter().any(Option::is_some) {
            state.snapshot_fx.to_vec()
        } else {
            Vec::new()
        },
        fun_snapshot_seeded: state.fun_snapshot_seeded,
        trim_all: state.trim_all.then_some(true),
        ui_locked: state.ui_locked.then_some(true),
        center_pan_on_split: state.center_pan_on_split.then_some(true),
        no_fader_double_click: state.no_fader_double_click.then_some(true),
        no_mouse_wheel: state.no_mouse_wheel.then_some(true),
        layout_panels: state.layout_panels.then_some(true),
        confirm_48v: (!state.confirm_48v).then_some(false),
        animations: (!state.animations).then_some(false),
        ui_sounds: (!state.ui_sounds).then_some(false),
        ui_sound_db: (state.ui_sound_db != crate::sounds::DEFAULT_VOLUME_DB)
            .then_some(state.ui_sound_db),
        peak_hold_s: (state.peak_hold_s != PEAK_HOLD_DEFAULT_S).then_some(state.peak_hold_s),
        meter_rms: (!state.meter_rms).then_some(false),
        over_samples: (state.over_samples != 1).then_some(state.over_samples),
        rms_plus3: state.rms_plus3.then_some(true),
        scroll_marks: (state.scroll_marks != [[None; 2]; 3]).then_some(state.scroll_marks),
        key_commands: (state.key_commands != crate::keycommands::defaults()).then_some(state.key_commands),
        free_routing: state.free_routing.then_some(true),
        midi_enabled: state.midi_enabled.then_some(true),
        mackie_on: state.mackie.on.then_some(true),
        mackie_device: state.mackie.device.clone(),
        mackie_meters: (!state.mackie.meters).then_some(false),
        mackie_extender: state.mackie.extender.clone(),
        mackie_extender_left: state.mackie.extender_left.then_some(true),
        theme: (state.theme != 0).then(|| theme::themes()[state.theme].id.to_string()),
        theme_auto: state.theme_schedule.on.then_some(true),
        theme_desktop: state.theme_desktop.then_some(true),
        theme_day: {
            let d = crate::themetime::ThemeSchedule::default();
            (state.theme_schedule.day != d.day).then(|| theme::themes()[state.theme_schedule.day].id.to_string())
        },
        theme_night: {
            let d = crate::themetime::ThemeSchedule::default();
            (state.theme_schedule.night != d.night).then(|| theme::themes()[state.theme_schedule.night].id.to_string())
        },
        theme_day_from: (state.theme_schedule.day_from != crate::themetime::ThemeSchedule::default().day_from)
            .then_some(state.theme_schedule.day_from),
        theme_night_from: (state.theme_schedule.night_from != crate::themetime::ThemeSchedule::default().night_from)
            .then_some(state.theme_schedule.night_from),
        midi_bindings: state.midi_bindings.clone(),
        trim_strips: state.trim_strips.iter().copied().collect(),
        no_trim_outputs: state.no_trim_outputs.clone(),
        engine_force_rate: Some(state.engine_force_rate),
        engine_force_quantum: Some(state.engine_force_quantum),
        cr_dim_db: Some(state.control_room.dim_db),
        cr_recall_db: Some(state.control_room.recall_db),
        cr_dimmed_main: state.control_room.dimmed_main,
        cr_fx_muted: state.control_room.fx_muted.clone(),
        cr_assign: Some(state.control_room.assign),
        cr_speaker_b: state.control_room.speaker_b.then_some(true),
        cr_mono: state.control_room.mono.then_some(true),
        cr_speaker_b_link: (!state.control_room.speaker_b_link).then_some(false),
        cr_mixes: crate::control_room::mixes_to_save(state),
        cr_phones_mix: None,
        cr_main_mix: None,
        cr_solo_mix: None,
        cr_tb_input: Some(state.control_room.talkback_input),
        cr_tb_dim_db: Some(state.control_room.talkback_dim_db),
        cr_tb_outputs: state.control_room.talkback_outputs.clone(),
        cr_lb_input: state.control_room.listenback_input,
        cr_lb_dim_db: Some(state.control_room.listenback_dim_db),
        cr_ext_pair: Some(state.control_room.ext_in_pair),
        cr_ext_db: Some(state.control_room.ext_in_db),
    }
}

/// Restores what `prefs_of` saved. Values are clamped to the same bounds
/// the live controls use, so a hand-edited file cannot open the app in a
/// state the UI could never reach.
pub fn apply_prefs(state: &mut TuxMix, prefs: crate::prefs::Prefs) {
    // Clamped as the live controls are (the harden review: a hand-edited
    // "cr_dim_db": 12 made Dim a 12 dB boost).
    use crate::control_room::{DIM_RANGE, EXT_IN_RANGE, RECALL_RANGE, TALKBACK_DIM_RANGE};
    if let Some(db) = prefs.cr_dim_db.filter(|d| d.is_finite()) {
        state.control_room.dim_db = db.clamp(DIM_RANGE.0, DIM_RANGE.1);
    }
    if let Some(db) = prefs.cr_recall_db.filter(|d| d.is_finite()) {
        state.control_room.recall_db = db.clamp(RECALL_RANGE.0, RECALL_RANGE.1);
    }
    // The last run quit or crashed while Main was dimmed: put it back.
    if let Some(i) = prefs.cr_tb_input.filter(|&i| i < state.device.inputs().len()) {
        state.control_room.talkback_input = i;
    }
    if let Some(db) = prefs.cr_tb_dim_db.filter(|d| d.is_finite()) {
        state.control_room.talkback_dim_db = db.clamp(TALKBACK_DIM_RANGE.0, TALKBACK_DIM_RANGE.1);
    }
    let pairs = state.device.output_pair_count();
    state.control_room.talkback_outputs =
        prefs.cr_tb_outputs.iter().copied().filter(|&p| p < pairs).collect();
    state.control_room.listenback_input =
        prefs.cr_lb_input.filter(|&i| i < state.device.inputs().len());
    if let Some(db) = prefs.cr_lb_dim_db {
        state.control_room.listenback_dim_db = db.clamp(
            crate::control_room::LISTENBACK_DIM_RANGE.0,
            crate::control_room::LISTENBACK_DIM_RANGE.1,
        );
    }
    if let Some(pair) = prefs.cr_ext_pair.filter(|&p| p < state.device.output_pair_count()) {
        state.control_room.ext_in_pair = pair;
    }
    if let Some(db) = prefs.cr_ext_db.filter(|d| d.is_finite()) {
        state.control_room.ext_in_db = db.clamp(EXT_IN_RANGE.0, EXT_IN_RANGE.1);
    }
    // The assignment first: a Dim left on belongs to the Main it was on.
    if let Some(assign) = prefs.cr_assign {
        let pairs = state.device.output_pair_count();
        let in_range = assign.main < pairs
            && assign.main_b.is_none_or(|b| b < pairs)
            && assign.phones.iter().flatten().all(|&p| p < pairs);
        if in_range {
            state.control_room.assign = assign.normalized();
        }
    }
    // Speaker B before the Dim recovery: a Dim left on belongs to the pair
    // that was playing.
    state.control_room.speaker_b =
        prefs.cr_speaker_b.unwrap_or(false) && state.control_room.assign.main_b.is_some();
    state.control_room.speaker_b_link = prefs.cr_speaker_b_link.unwrap_or(true);
    // Mono as it was left, where the driver can still make it.
    if prefs.cr_mono.unwrap_or(false) && state.device.can_mono() {
        if let Err(e) = crate::control_room::set_mono(state, true) {
            log::warn!("Mono not restored: {e}");
        }
    }
    // Overridden mixes, plus the fields older versions wrote them in (the
    // Phones and Main were PH3/4 and AN1/2 then).
    let mut mixes = prefs.cr_mixes.clone();
    mixes.extend(prefs.cr_phones_mix.clone().map(|mix| (1, mix)));
    mixes.extend(prefs.cr_main_mix.clone().map(|mix| (0, mix)));
    mixes.extend(prefs.cr_solo_mix.clone());
    crate::control_room::recover(state, prefs.cr_dimmed_main, mixes);
    crate::fx::recover_mute(state, prefs.cr_fx_muted.clone());
    // Main B is silent, or plays Main's mix, from the start.
    crate::control_room::reapply(state);
    if let Some(v) = prefs.view {
        state.view = v;
    }
    if let Some(open) = prefs.sidebar_open {
        state.sidebar_open = open;
    }
    if let Some(w) = prefs.sidebar_width {
        // A width under the floor was saved for the old, narrower sidebar
        // (210px by default): the counter starts at its own default instead
        // of squeezed to the floor.
        state.sidebar_width = if w < sidebar::MIN_WIDTH {
            sidebar::DEFAULT_WIDTH
        } else {
            w.min(sidebar::MAX_WIDTH)
        };
    }
    // `two_row` is the older boolean key: a saved `true` still means two
    // rows; `false` was merely the old default, so it maps to `Auto`.
    state.row_mode = match (prefs.row_mode, prefs.two_row) {
        (Some(mode), _) => mode,
        (None, Some(true)) => RowMode::Two,
        _ => RowMode::Auto,
    };
    // Mirrors, kept to pairs the device has and to one level (a target is
    // never a source), as `mixops::mirror` makes them.
    state.mirrors = crate::mixops::sane_mirrors(state, &prefs.mirrors);
    state.eq_presets = crate::eq_presets::normalized_slots(prefs.eq_presets.clone());
    state.mic_presets = prefs.mic_presets.clone();
    state.startup_mic_preset = prefs.startup_mic_preset.clone();
    if let Some(floor) = prefs.open_floor {
        state.open_floor = floor.min(2);
        if state.open_floor < 2 {
            state.source_floor = state.open_floor;
        }
    }
    if let Some(z) = prefs.ui_scale {
        state.ui_scale = z.clamp(theme::SCALE_MIN, theme::SCALE_MAX);
    } else {
        // Never saved: the first launch, see `Message::MonitorSize`.
        state.initial_zoom_pending = true;
    }
    state.labels = prefs
        .labels
        .into_iter()
        .filter(|(_, l)| !l.trim().is_empty())
        .collect();
    state.show_original_names = prefs.show_original_names;
    state.window_size = prefs.window_size;
    state.keep_in_tray = prefs.keep_in_tray.unwrap_or(true);
    state.tray_asked = prefs.tray_asked;
    state.tricks_found = prefs.tricks_found.clone();
    state.shimmers_shown = prefs.shimmers_shown.clone();
    state.tips_shown = prefs.tips_shown.clone();
    state.tips = !prefs.tips_off;
    state.helper_cat = !prefs.helper_cat_off;
    state.milestone_cards = !prefs.milestones_off;
    state.small_wins = !prefs.small_wins_off;
    state.plain_names = !prefs.plain_names_off;
    // Every setting kept, but Reverb and Echo always start off (the owner,
    // 2026-11-10: not used by default); their keys switch them on.
    state.fx = prefs.fx;
    state.fx.reverb_on = false;
    state.fx.echo_on = false;
    state.fx_presets = prefs.fx_presets.clone();
    state.fx_send_follow = prefs.fx_send_follow;
    state.fx_send_trim = None;
    // A file without the list seeds it from what is already true, silently
    // (`celebrate::check`).
    state.milestones_seeded = prefs.milestones.is_some();
    state.milestones = prefs.milestones.clone().unwrap_or_default();
    state.milestones_all_on = prefs.milestones_all_on.clone();
    state.guides_all_on = prefs.guides_all_on.clone();
    state.guides_done = prefs.guides_done.clone().unwrap_or_default();
    state.open_mic_kept = prefs.open_mics_kept.clone().unwrap_or_default().into_iter().collect();
    state.autoset = prefs.autoset.clone().unwrap_or_default().into_iter().collect();
    state.dyn_input = prefs.dynamics_input;
    state.tune_on = prefs.auto_tune.unwrap_or(false);
    state.nr_level = prefs.noise_removal.unwrap_or(0).min(2);
    state.low_delay = prefs.low_delay.unwrap_or(false);
    state.dyn_more = prefs.dyn_more.unwrap_or(false);
    state.dyn_fine_open = prefs.dyn_fine_open.unwrap_or(false);
    state.quick_voice_skipped = prefs.quick_voice_skipped.unwrap_or(false);
    state.d_hint_done = prefs.d_hint_done.unwrap_or(false);
    state.deess_level = prefs.de_esser.unwrap_or(0).min(2);
    state.record_folder = prefs.record_folder.as_ref().map(std::path::PathBuf::from);
    state.record_reverb = !(prefs.record_plain || prefs.record_no_reverb);
    state.record_echo = !(prefs.record_plain || prefs.record_no_echo);
    state.dyn_params = prefs.dynamics.unwrap_or(audra_fx::dynamics::presets()[0].1);
    if let Some(params) = prefs.dynamics_yours {
        let extras = prefs.dynamics_yours_extras.map(|(noise, deess, tune)| crate::dynamics_panel::Extras { noise, deess, tune });
        state.dyn_yours.insert((false, 0), crate::dynamics_panel::Yours { params, extras });
    }
    state.dyn_outs = prefs
        .dynamics_outputs
        .clone()
        .unwrap_or_default()
        .into_iter()
        .map(|d| (d.output, crate::dynamics_panel::OutDyn::kept(d.on, d.params)))
        .collect();
    if let Some(room) = prefs.room_eq {
        state.room_eq = room.sanitized();
    }
    state.launcher_entry_off = prefs.launcher_entry == Some(false);
    if let Some(tab) = prefs.open_page.as_deref().and_then(sidebar::page_of) {
        state.sidebar_tab = tab;
    }
    state.celebration_sounds = !prefs.celebration_sounds_off;
    // The knob as the user left it, the follow on top (the unit read back
    // knob plus follow, from the last run).
    if let Some(db) = prefs.fx_send_db.filter(|_| crate::fx::in_panels(state)) {
        crate::fx::sync_send_follow(state);
        let _ = state.device.set_fx_send(db);
    }
    // The other pairs' sends, where the driver has them (it starts them
    // off at every boot).
    if crate::fx::in_panels(state) {
        for (pair, &db) in &prefs.source_fx_send {
            let cid = crate::fx::SEND_PAIR_CHANNELS.iter().copied().find(|&c| tuxmix_core::device::source_send_pair(c) == Some(pair.as_str()));
            if let Some(cid) = cid.filter(|&c| state.device.has_source_fx_send(c)) {
                let _ = state.device.set_source_fx_send(cid, db);
            }
        }
    }
    sync_fx_loop(state);
    state.solo_exclusive = prefs.solo_exclusive.unwrap_or(true);
    state.control_room.live_mode = prefs.live_mode.unwrap_or(false);
    state.snapshot_keep = prefs.snapshot_keep.unwrap_or_default();
    state.trim_all = prefs.trim_all.unwrap_or(false);
    state.ui_locked = prefs.ui_locked.unwrap_or(false);
    crate::sounds::set_quiet(state.ui_locked);
    state.center_pan_on_split = prefs.center_pan_on_split.unwrap_or(false);
    state.no_fader_double_click = prefs.no_fader_double_click.unwrap_or(false);
    state.no_mouse_wheel = prefs.no_mouse_wheel.unwrap_or(false);
    state.layout_panels = prefs.layout_panels.unwrap_or(false);
    state.confirm_48v = prefs.confirm_48v.unwrap_or(true);
    state.animations = prefs.animations.unwrap_or(true);
    state.ui_sounds = prefs.ui_sounds.unwrap_or(true);
    state.ui_sound_db = prefs
        .ui_sound_db
        .unwrap_or(crate::sounds::DEFAULT_VOLUME_DB)
        .clamp(crate::sounds::VOLUME_RANGE.0, crate::sounds::VOLUME_RANGE.1);
    state.peak_hold_s = prefs
        .peak_hold_s
        .unwrap_or(PEAK_HOLD_DEFAULT_S)
        .clamp(PEAK_HOLD_RANGE_S.0, PEAK_HOLD_RANGE_S.1);
    state.meter_rms = prefs.meter_rms.unwrap_or(true);
    state.over_samples = prefs.over_samples.unwrap_or(1).clamp(1, 10);
    state.rms_plus3 = prefs.rms_plus3.unwrap_or(false);
    state.scroll_marks = prefs.scroll_marks.unwrap_or([[None; 2]; 3]);
    state.snapshot_names = std::array::from_fn(|i| prefs.snapshot_names.get(i).cloned().flatten());
    state.snapshot_fx = std::array::from_fn(|i| prefs.snapshot_fx.get(i).copied().flatten());
    state.fun_snapshot_seeded = prefs.fun_snapshot_seeded;
    state.hidden = prefs.hidden.iter().copied().collect();
    state.hidden_remote = prefs.hidden_remote.iter().copied().collect();
    state.key_commands = prefs.key_commands.unwrap_or_else(crate::keycommands::defaults);
    state.free_routing = prefs.free_routing.unwrap_or(false);
    state.midi_enabled = prefs.midi_enabled.unwrap_or(false);
    state.mackie.on = prefs.mackie_on.unwrap_or(false);
    state.mackie.device = prefs.mackie_device.clone();
    state.mackie.meters = prefs.mackie_meters.unwrap_or(true);
    state.mackie.extender = prefs.mackie_extender.clone();
    state.mackie.extender_left = prefs.mackie_extender_left.unwrap_or(false);
    state.theme = prefs.theme.as_deref().map_or(0, theme::theme_index);
    let defaults = crate::themetime::ThemeSchedule::default();
    state.theme_schedule = crate::themetime::ThemeSchedule {
        on: prefs.theme_auto.unwrap_or(false),
        day: prefs.theme_day.as_deref().map_or(defaults.day, theme::theme_index),
        night: prefs.theme_night.as_deref().map_or(defaults.night, theme::theme_index),
        day_from: prefs.theme_day_from.unwrap_or(defaults.day_from).min(24 * 60 - 1),
        night_from: prefs.theme_night_from.unwrap_or(defaults.night_from).min(24 * 60 - 1),
    };
    state.theme_desktop = prefs.theme_desktop.unwrap_or(false);
    // At launch the theme for now shows at once; fades are for changes.
    state.theme_shown = crate::themetime::wanted(state);
    state.theme_fade = None;
    theme::set_palette(theme::themes()[state.theme_shown].palette);
    state.midi_bindings = prefs.midi_bindings.clone();
    state.trim_strips = prefs.trim_strips.iter().copied().collect();
    state.no_trim_outputs = prefs.no_trim_outputs.clone();
    state.engine_force_rate = prefs.engine_force_rate.unwrap_or(0);
    state.engine_force_quantum = prefs.engine_force_quantum.unwrap_or(0);
    // A saved zoom may leave the sidebar no room beside the rows now that
    // it follows the zoom: fold it as a zoom step would.
    refold_for_zoom(state);
}

/// Brings the audio engine in line with the preferences at launch: the
/// rate / buffer forced here last time are forced again (PipeWire forgets
/// them when it restarts), then the clock is read. A choice of "Auto"
/// (`0`) is not re-sent, so launching TuxMix never lifts an override some
/// other tool set. The mock applies them to its simulated clock only.
pub fn restore_engine(state: &mut TuxMix) {
    if state.device.is_mock() {
        // The simulated clock starts at its defaults: the remembered
        // choices are the real PipeWire's.
        return;
    }
    if !state.device.rate_follows_sound_server() {
        return;
    }
    if state.engine_force_rate > 0 {
        if let Err(e) = pw_clock::force_rate(state.engine_force_rate) {
            log::warn!("Restoring the PipeWire rate failed: {e}");
        }
    }
    if state.engine_force_quantum > 0 {
        if let Err(e) = pw_clock::force_quantum(state.engine_force_quantum) {
            log::warn!("Restoring the PipeWire buffer size failed: {e}");
        }
    }
    state.engine = pw_clock::read();
    state.card_stream = pw_clock::card_stream(CARD_ID);
    state.driver_floor = pw_clock::driver_period_floor();
}

/// Writes the preferences if something changed (and a path is set).
fn flush_prefs(state: &mut TuxMix) {
    if !state.prefs_dirty {
        return;
    }
    state.prefs_dirty = false;
    if let Some(path) = state.prefs_path.clone() {
        match crate::prefs::save(&path, &prefs_of(state)) {
            Ok(()) => state.prefs_save_failed = None,
            Err(e) => {
                log::warn!("Failed to save GUI preferences: {e}");
                // Said once per reason, not at every save (issue #22: it
                // only reached the log).
                if state.prefs_save_failed.as_deref() != Some(e.as_str()) {
                    let at = Instant::now();
                    state.notice = Some((format!("Couldn't save your settings ({e}): what you change now is lost when Audra closes."), at));
                    state.notice_sticky_at = Some(at);
                    state.prefs_save_failed = Some(e);
                }
            }
        }
    }
}

