    #[test]
    fn a_takes_room_keeps_the_balance_you_hear() {
        // The mic at -6 dB in the mix you hear: the room 6 dB stronger
        // beside its voice, so the take (the voice before its fader) gets
        // the return doubled.
        assert!((super::wet_balance(1.0, 0.5) - 2.0).abs() < 1e-6);
        assert_eq!(super::wet_balance(0.8, 1.0), 0.8);
        // All but down: floored at -20 dB, not a blown-up room.
        assert!((super::wet_balance(1.0, 0.001) - 10.0).abs() < 1e-4);
        // Silent mic: the return as it is.
        assert_eq!(super::wet_balance(0.7, 0.0), 0.7);
        assert_eq!(super::wet_balance(0.0, 0.5), 0.0);
        // AN1's room fed at the send the unit has, the knob following its
        // fader (OpenCode's job 58), not the knob alone.
        let state = new(true, None, None);
        let p = super::take_wet_params(&state, 0);
        assert!((p.send - audra_fx::db_to_gain(crate::fx::send_heard_db(&state))).abs() < 1e-6);
    }

    #[test]
    fn hovering_mute_fx_lights_the_fx_key_it_holds() {
        // Critique #63's idea: the shared hue's link shown, no undo step.
        let mut state = new(true, None, None);
        let main = state.control_room.assign.main;
        let out = if state.device.outputs_one_per_pair() { main } else { main * 2 };
        crate::fx::set_return(&mut state, main, crate::fx::db_vol(-12.0));
        crate::fx::set_mute(&mut state, true);
        let before = state.undo_stack.len();
        let _ = update(&mut state, Message::MuteFxHover(true));
        assert_eq!(state.undo_stack.len(), before, "a hover is no undo step");
        assert!(crate::app::fx_mini_of(&state, ChannelId::Output(out)).is_some_and(|m| m.linked));
        let _ = update(&mut state, Message::MuteFxHover(false));
        assert!(crate::app::fx_mini_of(&state, ChannelId::Output(out)).is_some_and(|m| !m.linked));
        // The key leaving the layout under the pointer lets the glow go
        // (critique #64 A 8).
        let _ = update(&mut state, Message::MuteFxHover(true));
        let _ = update(&mut state, Message::SetView(View::Matrix));
        assert!(!state.mute_fx_hover);
        // Not held: a faint preview of what Mute FX would silence (Main's
        // return is up), none on an output it doesn't touch.
        crate::fx::set_mute(&mut state, false);
        let _ = update(&mut state, Message::MuteFxHover(true));
        assert!(crate::app::fx_mini_of(&state, ChannelId::Output(out)).is_some_and(|m| m.linked && !m.held));
        let phones = state.control_room.assign.phones_pairs()[0];
        let ph_out = if state.device.outputs_one_per_pair() { phones } else { phones * 2 };
        crate::fx::set_return(&mut state, phones, crate::fx::db_vol(-12.0));
        assert!(crate::app::fx_mini_of(&state, ChannelId::Output(ph_out)).is_some_and(|m| !m.linked), "Mute FX leaves the Phones");
    }

    #[test]
    fn mains_fx_key_is_held_while_mute_fx_silences_it() {
        // Critique #62 A 4: solid coral said "heard" under Mute FX.
        let mut state = new(true, None, None);
        let main = state.control_room.assign.main;
        let out = if state.device.outputs_one_per_pair() { main } else { main * 2 };
        crate::fx::set_return(&mut state, main, crate::fx::db_vol(-12.0));
        let mini = crate::app::fx_mini_of(&state, ChannelId::Output(out)).expect("Main's FX");
        assert!(!mini.held && mini.t > 0.0);
        crate::fx::set_mute(&mut state, true);
        let mini = crate::app::fx_mini_of(&state, ChannelId::Output(out)).expect("Main's FX");
        assert!(mini.held && mini.t > 0.0, "still on, held");
        // Nothing audible here (no effect on, no send): its level is kept,
        // not "silenced" (critique #68 A 4).
        assert!(mini.tip.contains("kept while Mute FX is on (Control Room)"), "{}", mini.tip);
    }

    #[test]
    fn rec_promises_no_effect_the_take_wont_hold() {
        // Critique #62 A 1: under Mute FX the take was dry while the Rec
        // key said "+ Reverb".
        let mut state = new(true, None, None);
        // Mute FX holds Main (as TotalMix), so Quick listens there.
        let pair = state.control_room.assign.main;
        state.quick_listen = Some(pair);
        // An effect on: the one model asks for it (`fx::block_in`).
        state.fx.reverb_on = true;
        crate::fx::set_return(&mut state, pair, crate::fx::db_vol(-12.0));
        // The send follows the mics' faders: AN1 up in the mix.
        let _ = update(&mut state, Message::VolumeChanged(ChannelId::Input(0), pair, 0.5));
        let _ = update(&mut state, Message::FxSend(-10.0));
        crate::app::settle_glides(&mut state);
        assert_eq!(crate::app::take_fx_heard(&state), Ok(()));
        crate::fx::set_mute(&mut state, true);
        crate::app::settle_glides(&mut state);
        assert!(crate::app::take_fx_heard(&state).is_err_and(|w| w.contains("Mute FX")), "{:?}", crate::app::take_fx_heard(&state));
        // On screen, the mix named (critique #64 A 7).
        let named = crate::app::heard_why_named(&state, crate::app::take_fx_heard(&state).unwrap_err());
        assert!(named.contains(&crate::sidebar::mix_name(&state, pair)), "{named}");
        crate::fx::set_mute(&mut state, false);
        crate::app::settle_glides(&mut state);
        assert_eq!(crate::app::take_fx_heard(&state), Ok(()));
        crate::fx::set_return(&mut state, pair, 0.0);
        assert_eq!(crate::app::take_fx_heard(&state), Err("the effects are turned down where you listen (that output's FX)"));
        crate::fx::set_return(&mut state, pair, crate::fx::db_vol(-12.0));
        let _ = update(&mut state, Message::FxSend(crate::fx::OFF_DB));
        crate::app::settle_glides(&mut state);
        assert_eq!(crate::app::take_fx_heard(&state), Err("this mic sends nothing to the effects (its FX send)"));
        let named = crate::app::heard_why_named(&state, "this mic sends nothing to the effects (its FX send)");
        assert!(named.starts_with("AN1"), "the mic named: {named}");
    }

    #[test]
    fn rec_has_a_switch_for_each_effect() {
        // The owner, 2026-11-15: "a button to include in record on and off
        // per Echo or Reverb".
        let mut state = new(true, None, None);
        state.fx.reverb_on = true;
        state.fx.echo_on = true;
        assert!(state.record_reverb && state.record_echo, "both go in by default");
        let fx = super::take_effects(&state);
        assert!(fx.reverb_on && fx.echo_on);
        assert_eq!(super::take_fx_words(&state), "Reverb & Echo");

        let _ = update(&mut state, Message::SetRecordFx(crate::fx::Unit::Echo, false));
        let fx = super::take_effects(&state);
        assert!(fx.reverb_on && !fx.echo_on, "the Echo is left out of the take, still heard");
        assert!(state.fx.echo_on, "what you hear is untouched");
        assert_eq!(super::take_fx_words(&state), "Reverb");
        assert!(!super::take_wet_params(&state, 0).fx.echo_on, "the take's engine runs no Echo");

        // Reverb off with only it going in: plain, and said why.
        state.fx.reverb_on = false;
        assert_eq!(super::take_fx(&state), Err(Some("Reverb is off, and Echo is left out of takes")));

        // Both switches off: no effects asked for (no reason to give).
        let _ = update(&mut state, Message::SetRecordFx(crate::fx::Unit::Reverb, false));
        assert_eq!(super::take_fx(&state), Err(None));
    }

