    #[test]
    fn output_meters_show_what_the_hardware_plays() {
        // AN1 alone, at 0 dB into Main and off in the Phones' own mix.
        let mut state = new(true, None, None);
        let an1 = ChannelId::Input(0);
        for i in 0..state.device.inputs().len() {
            for pair in 0..state.device.output_pair_count() {
                let v = if i == 0 && pair == 0 { 1.0 } else { 0.0 };
                let _ = update(&mut state, Message::VolumeChanged(ChannelId::Input(i), pair, v));
            }
        }
        for c in 0..state.device.playbacks().len() {
            for pair in 0..state.device.output_pair_count() {
                let _ = update(&mut state, Message::VolumeChanged(ChannelId::Playback(c), pair, 0.0));
            }
        }
        let n_out = state.device.outputs().len();
        let mut meters_in = vec![0.0; state.device.inputs().len()];
        meters_in[0] = 0.5;
        let meters = |state: &TuxMix| {
            let (ins, pbs) = crate::control_room::heard_side_levels(state);
            power_sum_output_meters(&ins, &meters_in, &pbs, &[], n_out)
        };
        let out = meters(&state);
        // AN1 at 0.5 into Main, centred: -3 dB on each side (0.35).
        assert!(out[0] > 0.3 && out[2] == 0.0, "Main reads AN1, the Phones nothing: {out:?}");
        // Cue Main on the Phones: they now read AN1 too.
        let _ = update(&mut state, Message::CueChanged(ChannelId::Output(0), true));
        let out = meters(&state);
        assert!(out[2] > 0.3 && out[3] > 0.3, "the cued mix shows on the Phones: {out:?}");
        let _ = update(&mut state, Message::CueChanged(ChannelId::Output(0), false));
        // A muted source no longer reads on Main.
        let _ = update(&mut state, Message::Mute(an1, true));
        assert_eq!(meters(&state)[0], 0.0, "a muted AN1 is silent on Main");
        // Post-fader (manual 21.1): the output's own fader and mute apply.
        let mut outs = vec![
            tuxmix_core::OutputChannel::new(0, "AN1"),
            tuxmix_core::OutputChannel::new(1, "AN2"),
        ];
        outs[0].volume = 0.5;
        outs[1].mute = true;
        let mut levels = vec![0.8, 0.8];
        super::post_fader(&mut levels, &outs);
        assert_eq!(levels, vec![0.4, 0.0]);
    }

    #[test]
    fn cue_is_exclusive_across_outputs() {
        // Host-side Cue (control_room): one output's submix plays on the
        // Phones at a time, and engaging another output's Cue replaces it
        // rather than both reading as cued at once.
        let mut state = new(true, None, None);
        let a = ChannelId::Output(0); // pair 0, Main
        let b = ChannelId::Output(4); // pair 2, AS1/2

        let _ = update(&mut state, Message::CueChanged(a, true));
        assert_eq!(state.control_room.cue, Some(0));

        let _ = update(&mut state, Message::CueChanged(b, true));
        assert_eq!(state.control_room.cue, Some(2), "a should no longer be cued");

        let _ = update(&mut state, Message::CueChanged(b, false));
        assert_eq!(state.control_room.cue, None, "explicit off clears it");
    }

    #[test]
    fn eq_for_record_and_optical_out_format_toggles_reach_device_settings() {
        let mut state = new(true, None, None);
        assert!(!state.device.settings().eq_for_record);
        assert!(!state.device.settings().optical_out_spdif);

        let _ = update(&mut state, Message::EqForRecordChanged(true));
        assert!(state.device.settings().eq_for_record);
        assert!(!state.device.settings().optical_out_spdif);

        let _ = update(&mut state, Message::OpticalOutFormatChanged(true));
        assert!(state.device.settings().optical_out_spdif);

        let _ = update(&mut state, Message::EqForRecordChanged(false));
        assert!(!state.device.settings().eq_for_record);
        assert!(
            state.device.settings().optical_out_spdif,
            "toggling EQ-for-Record must not stomp the SPDIF flag (shared settings-word register)"
        );
    }

