    #[test]
    fn speaker_b_and_main_b_come_back_right_after_a_restart() {
        let mut state = with_main_b();
        let mic = ChannelId::Input(0);
        let _ = update(&mut state, Message::SpeakerBToggle);
        let saved = prefs_of(&state);
        // The next start reads Main B's controls back (Main's mix, as it
        // was playing) as if they were its own mix...
        let mut next = new(true, None, None);
        let _ = next.device.set_volume(mic, 0, 0.7);
        let _ = next.device.set_volume(mic, 2, 0.7);
        apply_prefs(&mut next, saved);
        // ...and recovery puts Main B's own mix back in the model, while
        // the hardware plays Main's mix there with Speaker B still on.
        assert!(next.control_room.speaker_b);
        assert_eq!(next.device.volume(mic, 2).unwrap(), 0.5);
        assert_eq!(hw(&next, mic, 2), 0.7);
        assert_eq!(hw(&next, mic, 0), 0.0);
    }

    #[test]
    fn main_b_stays_silent_through_undo_and_plays_its_mix_once_unassigned() {
        let mut state = with_main_b();
        let mic = ChannelId::Input(0);
        let _ = update(&mut state, Message::VolumeChanged(mic, 1, 0.2));
        let _ = update(&mut state, Message::Undo);
        assert_eq!(hw(&state, mic, 2), 0.0, "the scene Undo applies does not unmute Main B");
        let assign = state.control_room.assign.with_main_b(None);
        let _ = update(&mut state, Message::SetAssign(assign));
        // From the silence it held, up as a glide (OpenCode's job 44).
        assert!(hw(&state, mic, 2) < 0.01, "not in one write");
        super::settle_glides(&mut state);
        assert_eq!(hw(&state, mic, 2), 0.5, "AS1/2 plays its own mix again");
        let _ = update(&mut state, Message::SpeakerBToggle);
        assert!(!state.control_room.speaker_b, "no Speaker B without a Main B");
    }

    #[test]
    fn a_submix_copies_onto_another_output_and_clears_with_undo() {
        let mut state = new(true, None, None);
        let (mic, music) = (ChannelId::Input(0), ChannelId::Playback(0));
        let _ = state.device.set_volume(mic, 0, 0.6);
        let _ = state.device.set_pan(mic, 0, -40);
        let _ = state.device.set_volume(music, 0, 0.9);
        let main = output_strip(&state, 0);
        let _ = update(&mut state, Message::MixCopy(main));
        let target = output_strip(&state, 2);
        let _ = update(&mut state, Message::MixPaste(target));
        // A rise comes as a glide (the level audit).
        super::settle_glides(&mut state);
        assert_eq!(state.device.volume(mic, 2).unwrap(), 0.6);
        assert_eq!(state.device.pan(mic, 2).unwrap(), -40);
        assert_eq!(state.device.volume(music, 2).unwrap(), 0.9);
        let _ = update(&mut state, Message::MixClear(target));
        assert_eq!(state.device.volume(mic, 2).unwrap(), 0.0);
        let _ = update(&mut state, Message::Undo);
        super::settle_glides(&mut state);
        assert_eq!(state.device.volume(mic, 2).unwrap(), 0.6, "Undo brings the submix back");
        assert!(!crate::mixops::can_paste(&state, output_strip(&state, 0)), "not onto itself");
    }

    #[test]
    fn a_mirror_follows_its_source_until_the_target_is_edited() {
        let mut state = new(true, None, None);
        let mic = ChannelId::Input(2);
        let main = output_strip(&state, 0);
        let _ = update(&mut state, Message::MixCopy(main));
        let target = output_strip(&state, 3);
        let _ = update(&mut state, Message::MixMirror(target));
        assert_eq!(crate::mixops::mirrored_from(&state, 3), Some(0));
        let _ = update(&mut state, Message::VolumeChanged(mic, 0, 0.5));
        super::settle_glides(&mut state);
        assert_eq!(state.device.volume(mic, 3).unwrap(), 0.5, "the mirror follows (gliding up)");
        assert_eq!(crate::mixops::mirrored_from(&state, 3), Some(0), "its own glide doesn't end the mirror");
        // A direct edit of the target ends the mirror and is kept.
        let _ = update(&mut state, Message::VolumeChanged(mic, 3, 0.2));
        assert_eq!(crate::mixops::mirrored_from(&state, 3), None);
        let _ = update(&mut state, Message::VolumeChanged(mic, 0, 0.8));
        assert_eq!(state.device.volume(mic, 3).unwrap(), 0.2);
        // Saved and restored with the prefs.
        let _ = update(&mut state, Message::MixMirror(target));
        let mut next = new(true, None, None);
        apply_prefs(&mut next, prefs_of(&state));
        assert_eq!(next.mirrors, vec![(0, 3)]);
    }

    /// Undo and Redo carry the mirrors: a `Scene` is the unit's state only,
    /// so Undo put a pair's mix back and left its mirror as it stood (the
    /// safety audit of 2026-11-17).
    #[test]
    fn undo_and_redo_put_a_mirror_back_with_its_mix() {
        let mut state = new(true, None, None);
        let mic = ChannelId::Input(2);
        let main = output_strip(&state, 0);
        let target = output_strip(&state, 3);
        let _ = update(&mut state, Message::VolumeChanged(mic, 0, 0.5));
        let _ = update(&mut state, Message::MixCopy(main));
        // Mirroring undone: the mirror goes, and comes back with Redo.
        let _ = update(&mut state, Message::MixMirror(target));
        super::settle_glides(&mut state);
        assert_eq!(crate::mixops::mirrored_from(&state, 3), Some(0));
        assert_eq!(state.device.volume(mic, 3).unwrap(), 0.5);
        let _ = update(&mut state, Message::Undo);
        super::settle_glides(&mut state);
        assert_eq!(crate::mixops::mirrored_from(&state, 3), None, "Undo takes the mirror back");
        assert_eq!(state.device.volume(mic, 3).unwrap(), 0.0);
        let _ = update(&mut state, Message::Redo);
        assert_eq!(crate::mixops::mirrored_from(&state, 3), Some(0), "Redo mirrors again");
        super::settle_glides(&mut state);
        assert_eq!(state.device.volume(mic, 3).unwrap(), 0.5, "the mirrored mix is back with Redo");
        // Undone again before its glide is over, Redo still brings the
        // whole mirrored mix, not the part that had risen.
        let _ = update(&mut state, Message::Undo);
        super::settle_glides(&mut state);
        let _ = update(&mut state, Message::Redo);
        let _ = update(&mut state, Message::Undo);
        let _ = update(&mut state, Message::Redo);
        super::settle_glides(&mut state);
        assert_eq!(state.device.volume(mic, 3).unwrap(), 0.5, "Redo after a quick Undo keeps the glide's end");
        // A direct edit of the target ends the mirror; Undo brings both back.
        state.undo_gesture = None;
        let _ = update(&mut state, Message::VolumeChanged(mic, 3, 0.2));
        assert_eq!(crate::mixops::mirrored_from(&state, 3), None);
        let _ = update(&mut state, Message::Undo);
        super::settle_glides(&mut state);
        assert_eq!(crate::mixops::mirrored_from(&state, 3), Some(0), "the mirror is back with the mix it had");
        assert_eq!(state.device.volume(mic, 3).unwrap(), 0.5);
        // Stopping a mirror is a step of its own.
        let _ = update(&mut state, Message::MixMirrorStop(target));
        assert_eq!(crate::mixops::mirrored_from(&state, 3), None);
        let _ = update(&mut state, Message::Undo);
        assert_eq!(crate::mixops::mirrored_from(&state, 3), Some(0), "a stopped mirror comes back");
        // A step that never touched a mirror leaves them alone.
        state.undo_gesture = None;
        let _ = update(&mut state, Message::VolumeChanged(mic, 1, 0.3));
        let _ = update(&mut state, Message::Undo);
        assert_eq!(crate::mixops::mirrored_from(&state, 3), Some(0));
    }

    #[test]
    fn a_channel_mix_pastes_onto_a_channel_of_the_same_kind() {
        let mut state = new(true, None, None);
        let (from, to) = (ChannelId::Input(2), ChannelId::Input(4));
        let _ = state.device.set_volume(from, 0, 0.3);
        let _ = state.device.set_volume(from, 1, 0.7);
        let _ = update(&mut state, Message::MixCopy(from));
        assert!(!crate::mixops::can_paste(&state, ChannelId::Playback(0)), "inputs onto inputs only");
        let _ = update(&mut state, Message::MixPaste(to));
        super::settle_glides(&mut state);
        assert_eq!(state.device.volume(to, 0).unwrap(), 0.3);
        assert_eq!(state.device.volume(to, 1).unwrap(), 0.7);
        let _ = update(&mut state, Message::MixClear(to));
        assert_eq!(state.device.volume(to, 1).unwrap(), 0.0);
        assert!(!is_undoable(&Message::MixCopy(from)));
    }

