        let assign = state.control_room.assign.with_phones(1, Some(2));
        let _ = update(&mut state, Message::SetAssign(assign));
        let music = ChannelId::Playback(0);
        for pair in [1, 2] {
            let _ = state.device.set_volume(music, pair, 1.0);
        }
