        state.window_size = Some((1280.0, 800.0));
        super::set_open_floor(&mut state, 0);
        assert!(super::one_floor_open(&state) && !super::floor_is_open(&state, 2), "outputs folded at 1280x800");
        // The placard's note or a key opens the Phones' panel: its row opens.
