    #[test]
    fn an_open_mic_warning_that_goes_and_comes_back_is_amber_again() {
        // Issue #35, the recommended pick: "Take it out", then Undo, brought
        // the warning back quiet.
        let mut state = new(true, None, None);
        let (i, cid) = (0usize, ChannelId::Input(0));
        let pair = state.control_room.assign.main;
        let _ = update(&mut state, Message::Gain(i, 30));
        let _ = state.device.set_volume(cid, pair, 0.7);
        let out = if state.device.outputs_one_per_pair() { pair } else { pair * 2 };
        let _ = state.device.set_volume(ChannelId::Output(out), 0, 0.8);
        state.open_mic_heard.insert(cid, Instant::now());
        let _ = update(&mut state, Message::OpenMicExpand);
        let _ = update(&mut state, Message::OpenMicExpand);
        assert!(super::open_mic_quiet(&state, cid, pair), "seen: quiet");
        // A pause in talking keeps it quiet: the routing is unchanged.
        state.open_mic_heard.clear();
        let _ = update(&mut state, Message::Tick);
        state.open_mic_heard.insert(cid, Instant::now());
        assert!(super::open_mic_quiet(&state, cid, pair), "a pause doesn't relight it");
        // The send taken out, then back: amber.
        let _ = state.device.set_volume(cid, pair, 0.0);
        let _ = update(&mut state, Message::Tick);
        let _ = state.device.set_volume(cid, pair, 0.7);
        assert!(!super::open_mic_quiet(&state, cid, pair), "back: amber again");
    }

    #[test]
    fn the_open_mic_line_goes_quiet_once_seen_until_the_mic_gets_hotter() {
        // The owner's pick after critique #43.
        let mut state = new(true, None, None);
        // AN1 hot (gain 30) and sent into Main, Main up, heard lately.
        let (i, cid) = (0usize, ChannelId::Input(0));
        let pair = state.control_room.assign.main;
        let _ = update(&mut state, Message::Gain(i, 30));
        let _ = state.device.set_volume(cid, pair, 0.7);
        let out = if state.device.outputs_one_per_pair() { pair } else { pair * 2 };
        let _ = state.device.set_volume(ChannelId::Output(out), 0, 0.8);
        state.open_mic_heard.insert(cid, Instant::now());
        assert_eq!(crate::sidebar::open_mic_shown(&state), Some((cid, pair)), "the warning shows");
        assert!(!super::open_mic_quiet(&state, cid, pair), "amber until seen");
        let _ = update(&mut state, Message::OpenMicExpand);
        assert!(super::open_mic_quiet(&state, cid, pair), "seen: quiet");
        let _ = update(&mut state, Message::OpenMicExpand);
        assert!(super::open_mic_quiet(&state, cid, pair), "closing it keeps it quiet");
        let g = state.device.inputs()[i].gain.unwrap_or(0);
        let _ = update(&mut state, Message::Gain(i, g.saturating_sub(3)));
        assert!(super::open_mic_quiet(&state, cid, pair), "quieter still: quiet");
        let _ = update(&mut state, Message::Gain(i, g + 3));
        assert!(!super::open_mic_quiet(&state, cid, pair), "hotter than seen: amber again");
        // Job 56's cases: seen again, then PAD off (PAD_DB, 11 dB, hotter at the same
        // gain number), a send turned up, 48V off (cooler) and another mic.
        let _ = update(&mut state, Message::OpenMicExpand);
        let _ = update(&mut state, Message::OpenMicExpand);
        assert!(super::open_mic_quiet(&state, cid, pair));
        let _ = update(&mut state, Message::Pad(i, true));
        let _ = update(&mut state, Message::OpenMicExpand);
        let _ = update(&mut state, Message::OpenMicExpand);
        assert!(super::open_mic_quiet(&state, cid, pair), "seen with PAD on");
        let _ = update(&mut state, Message::Pad(i, false));
        super::settle_glides(&mut state);
        assert!(!super::open_mic_quiet(&state, cid, pair), "PAD off: PAD_DB hotter, amber");
        let _ = update(&mut state, Message::OpenMicExpand);
        let _ = update(&mut state, Message::OpenMicExpand);
        let _ = state.device.set_volume(cid, pair, 1.0);
        assert!(!super::open_mic_quiet(&state, cid, pair), "its send 3 dB+ up: amber");
        let _ = update(&mut state, Message::OpenMicExpand);
        let _ = update(&mut state, Message::OpenMicExpand);
        let _ = state.device.set_input_phantom(i, true);
        assert!(!super::open_mic_quiet(&state, cid, pair), "48V newly on: amber");
        let _ = update(&mut state, Message::OpenMicExpand);
        let _ = update(&mut state, Message::OpenMicExpand);
        let _ = state.device.set_input_phantom(i, false);
        assert!(super::open_mic_quiet(&state, cid, pair), "48V off is cooler: still quiet");
        // The speakers' side (critique #44): Main up 3 dB+ brings it back.
        let _ = state.device.set_volume(ChannelId::Output(out), 0, 0.3);
        let _ = update(&mut state, Message::OpenMicExpand);
        let _ = update(&mut state, Message::OpenMicExpand);
        assert!(super::open_mic_quiet(&state, cid, pair), "seen with Main lower");
        let _ = state.device.set_volume(ChannelId::Output(out), 0, 1.0);
        assert!(!super::open_mic_quiet(&state, cid, pair), "Main turned up: amber");
        let _ = update(&mut state, Message::OpenMicExpand);
        let _ = update(&mut state, Message::OpenMicExpand);
        assert!(super::open_mic_quiet(&state, cid, pair));
        // Another mic, hot in Main: named first, in amber.
        let an2 = ChannelId::Input(1);
        let _ = update(&mut state, Message::Gain(1, 30));
        let _ = state.device.set_volume(an2, pair, 0.7);
        state.open_mic_heard.insert(an2, Instant::now());
        if !state.device.input_pair_linked(0) {
            assert_eq!(crate::sidebar::open_mic_shown(&state), Some((an2, pair)), "the new mic is named");
            assert!(!super::open_mic_quiet(&state, an2, pair), "and amber");
            // Its answers opened for AN2: AN1 turning hotter doesn't take
            // the press over (OpenCode's job 60).
            let _ = update(&mut state, Message::OpenMicExpand);
            assert_eq!(state.open_mic_held, Some((an2, pair)));
            let _ = update(&mut state, Message::Gain(0, 45));
            assert!(!super::open_mic_quiet(&state, cid, pair), "AN1 hotter: news");
            assert_eq!(crate::sidebar::open_mic_shown(&state), Some((an2, pair)), "held while its answers are open");
            let _ = update(&mut state, Message::OpenMicExpand);
            assert_eq!(crate::sidebar::open_mic_shown(&state), Some((cid, pair)), "closed, the news is named");
        }
    }

    #[test]
