        assert_eq!(eq_preset_now(&state, 0).as_deref(), Some(factory[1].name.as_ref()));
        // A band moved by hand: no preset any more.
        let g = state.device.inputs()[0].eq.unwrap().bands[0].gain_db;
        let _ = state.device.set_eq_band_gain(0, 0, eq_plot::clamp_gain(g + 3.0));
