    #[test]
    fn a_held_peak_never_sits_under_the_bar() {
        let mut m = MeterAnim::new();
        for _ in 0..20 {
            m.step(0.8);
        }
        m.hold_peak(0.8, std::time::Duration::ZERO);
        // Quiet now: the bar falls back over a few ticks; a new hold taken
        // as it falls stays at or over it.
        m.step(0.05);
        m.hold_peak(0.05, std::time::Duration::ZERO);
        assert!(m.frame().peak >= m.frame().value - 1e-6, "peak {} under bar {}", m.frame().peak, m.frame().value);
    }

    #[test]
    fn only_the_fx_key_that_opened_settings_rings() {
        // Critique #60 A 2: one panel, one ring (the wrench's).
        let mut state = new(true, None, None);
        let cid = ChannelId::Output(0);
        let _ = update(&mut state, Message::OpenFx(cid));
        assert!(state.fx_opened.contains(&cid), "opened by its FX key");
        let _ = update(&mut state, Message::ToggleFlyout(cid, strip::FlyoutKind::Settings));
        assert!(!state.fx_opened.contains(&cid), "closed by the wrench");
        let _ = update(&mut state, Message::ToggleFlyout(cid, strip::FlyoutKind::Settings));
        assert!(!state.fx_opened.contains(&cid), "opened by the wrench: not the FX key's");
        let _ = update(&mut state, Message::OpenFx(cid));
        assert!(state.fx_opened.contains(&cid), "already open, pressed: the FX key's now");
        // A second strip's FX key leaves the first one's ring (job 62).
        let other = ChannelId::Output(2);
        let _ = update(&mut state, Message::OpenFx(other));
        assert!(state.fx_opened.contains(&other));
        assert!(state.flyout_open.contains(&(cid, strip::FlyoutKind::Settings)), "both panels open");
        assert!(state.fx_opened.contains(&cid), "the first strip keeps its ring");
    }

    #[test]
    fn a_saved_take_offers_its_folder_until_a_newer_notice() {
        // The owner, 2026-11-13: "when finished recording offer to open the
        // folder where the recording is saved."
        let mut state = new(true, None, None);
        let dir = std::path::PathBuf::from("/home/someone/Music/Audra");
        super::say_take(&mut state, crate::recorder::RecState::Saved { path: dir.join("take.wav"), seconds: 12.0, why: None, parts: 1, gaps: 0, with_fx: (false, false) });
        assert_eq!(super::notice_folder(&state), Some(dir.as_path()), "the take's own folder");
        assert!(matches!(super::notice_key(&state), Some(super::NoticeKey::OpenFolder)));
        // Kept past its usual time, as an Undo notice is.
        state.notice.as_mut().unwrap().1 = Instant::now() - NOTICE_FOR - Duration::from_secs(1);
        let at = state.notice.as_ref().unwrap().1;
        state.notice_folder.as_mut().unwrap().0 = at;
        let _ = update(&mut state, Message::Tick);
        assert!(super::notice_folder(&state).is_some(), "still offered");
        // Its key opens it (never in a test) and the notice goes.
        let _ = update(&mut state, Message::NoticeOpenFolder);
        assert!(state.notice.is_none());
        // A take that failed offers nothing; a newer notice takes the key away.
        super::say_take(&mut state, crate::recorder::RecState::Saved { path: dir.join("b.wav"), seconds: 3.0, why: None, parts: 1, gaps: 2, with_fx: (false, false) });
        assert!(state.notice.as_ref().is_some_and(|(t, _)| t.contains("It has 2 dropouts: the computer was too busy")), "{:?}", state.notice);
        state.notice = Some(("Something else.".into(), Instant::now() + Duration::from_millis(5)));
        assert!(super::notice_key(&state).is_none());
        super::say_take(&mut state, crate::recorder::RecState::Failed("no unit".into()));
        assert!(super::notice_key(&state).is_none(), "a failed take has no folder to show");
    }

    #[test]
    fn a_takes_note_says_with_reverb_only_when_some_went_in() {
        let dir = std::env::temp_dir().join(format!("audra-take-fx-{}", std::process::id()));
        let mut state = new(true, None, None);
        state.record_folder = Some(dir.clone());
        state.tips = true;
        state.tips_shown.clear();
        let saved = |with_fx| crate::recorder::RecState::Saved { path: dir.join("t.wav"), seconds: 4.0, why: None, parts: 1, gaps: 0, with_fx };
        let feed = || crate::recorder::WetFeed::new(take_wet_params(&new(true, None, None), 0));
        state.rec_wet = Some((feed(), 0));
        super::say_take(&mut state, saved((true, true)));
        let said = state.notice.clone().map(|(w, _)| w).unwrap_or_default();
        assert!(said.contains("with Reverb & Echo"), "{said}");
        assert!(said.contains("can't be taken out"), "the first one says what that means: {said}");
        assert!(state.rec_wet.is_none(), "let go with the take");
        // Said once.
        state.rec_wet = Some((feed(), 0));
        super::say_take(&mut state, saved((true, true)));
        let said = state.notice.clone().map(|(w, _)| w).unwrap_or_default();
        assert!(said.contains("with Reverb & Echo") && !said.contains("can't be taken out"), "{said}");
        // A take that held only the Reverb says so, whatever the switches
        // are at the end (OpenCode's job 61).
        state.rec_wet = Some((feed(), 0));
        super::say_take(&mut state, saved((true, false)));
        let said = state.notice.clone().map(|(w, _)| w).unwrap_or_default();
        assert!(said.contains("with Reverb ") && !said.contains("Echo"), "{said}");
        // Asked for, but nothing went in (the send or return at zero).
        state.rec_wet = Some((feed(), 0));
        super::say_take(&mut state, saved((false, false)));
        let said = state.notice.clone().map(|(w, _)| w).unwrap_or_default();
        assert!(!said.contains("with Reverb") && said.contains("No effects in it"), "{said}");
        // Not asked for: neither.
        super::say_take(&mut state, saved((false, false)));
        let said = state.notice.clone().map(|(w, _)| w).unwrap_or_default();
        assert!(!said.contains("Reverb") && !said.contains("No effects"), "{said}");
        let _ = std::fs::remove_dir_all(&dir);
    }

