    #[test]
    fn linking_an_output_pair_never_jumps_its_right_side() {
        // The level audit: the right side took the left's level at once.
        let mut state = new(true, None, None);
        if state.device.outputs_one_per_pair() {
            return;
        }
        let (l, r) = (4usize, 5usize);
        let _ = update(&mut state, Message::StereoLinkChanged(ChannelId::Output(l), false));
        let _ = state.device.set_volume(ChannelId::Output(l), 0, 1.0);
        let _ = state.device.set_volume(ChannelId::Output(r), 0, 0.01);
        match &mut state.device {
            DeviceHandle::Mock(m) => m.log_writes(true),
            _ => unreachable!(),
        }
        let _ = update(&mut state, Message::StereoLinkChanged(ChannelId::Output(l), true));
        super::settle_glides(&mut state);
        assert!((state.device.outputs()[r].volume - 1.0).abs() < 1e-3, "both end at the left's level");
        let writes = match &state.device {
            DeviceHandle::Mock(m) => m.writes().to_vec(),
            _ => Vec::new(),
        };
        let db = |v: f32| (20.0 * v.max(1e-6).log10()).max(-60.0);
        let mut prev = db(0.01);
        for w in writes {
            if let tuxmix_core::mock::MockWrite::OutputVolume(c, v) = w {
                if c == r {
                    assert!(db(v) <= prev + RAMP_OVER_DB as f32 + 0.01, "the right side jumped {prev:.1} -> {:.1}", db(v));
                    prev = prev.max(db(v));
                }
            }
        }
    }

